INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$5105ca38$SATQ$, $SATQ$55d8d07f-2534-4a35-9ee9-6b05192a38c6$SATQ$::uuid, $SATQ$071f4a43-1714-4bd6-a318-577096113190$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Several artworks found among the ruins of the ancient Roman city of Pompeii depict a female figure fishing with a cupid nearby. Some scholars have asserted that the figure is the goddess Venus, since she is known to have been linked with cupids in Roman culture, but University of Leicester archaeologist Carla Brain suggests that cupids may have also been associated with fishing generally. The fact that a cupid is shown near the female figure, therefore, <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"d17419de-663c-4828-a1f3-e0078a9fcb6a","content":"<p>is not conclusive evidence that the figure is Venus.</p>"},{"id":"32192185-bf4d-4e6b-a680-6817a1055e47","content":"<p>suggests that Venus was often depicted fishing.</p>"},{"id":"5163387c-9b1a-434d-9a05-1af446766215","content":"<p>eliminates the possibility that the figure is Venus.&nbsp;</p>"},{"id":"6dfdb26a-a914-4a24-9dae-e56b4e368861","content":"<p>would be difficult to account for if the figure is not Venus.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["d17419de-663c-4828-a1f3-e0078a9fcb6a"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it presents the conclusion that most logically completes the text&rsquo;s discussion about the significance of the cupid found at Pompeii. The text indicates that the cupid is near a statue of a female figure who is fishing, and it goes on to indicate that because Venus is associated with cupids, some scholars believe the female figure to be the goddess Venus. But the text then says that, according to archaeologist Carla Brain, cupids may have also been associated with the activity of fishing, which, if true, would suggest that the mere appearance of a cupid near a female figure engaged in fishing does not indicate with certainty that the figure is Venus (that is, the cupid might be associated with fishing, and the figure might be anyone at all). </p><p>Choice B is incorrect because the text says nothing about how often Venus was depicted fishing in Roman art: it only implies that in certain instances a female figure may or may not be Venus. Choice C is incorrect because Carla Brain&rsquo;s proposed explanation for the presence of the cupids makes no reference to the female figure, and so the possibility that the figure in the artworks is in fact Venus cannot be definitively eliminated. Choice D is incorrect because there is nothing in the text to suggest that the only reasonable way to interpret the figure is as Venus. </p>$SATQ$, false, 0, $SATQ$OSP-004-INF$SATQ$, $SATQ$$SATQ$, $SATQ$bbe3b90c-08e2-4190-b80c-cd067ddfd0f2$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"5105ca38","external_id":"55d8d07f-2534-4a35-9ee9-6b05192a38c6","vaultid":"071f4a43-1714-4bd6-a318-577096113190","uId":"e29cb068-d9bf-4825-b879-95d1b474bb36","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Several artworks found among the ruins of the ancient Roman city of Pompeii depict a female figure fishing with a cupid nearby. Some scholars have asserted that the figure is the goddess Venus, since she is known to have been linked with cupids in Roman culture, but University of Leicester archaeologist Carla Brain suggests that cupids may have also been associated with fishing generally. The fact that a cupid is shown near the female figure, therefore, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"d17419de-663c-4828-a1f3-e0078a9fcb6a","content":"<p>is not conclusive evidence that the figure is Venus.</p>"},{"id":"32192185-bf4d-4e6b-a680-6817a1055e47","content":"<p>suggests that Venus was often depicted fishing.</p>"},{"id":"5163387c-9b1a-434d-9a05-1af446766215","content":"<p>eliminates the possibility that the figure is Venus.&nbsp;</p>"},{"id":"6dfdb26a-a914-4a24-9dae-e56b4e368861","content":"<p>would be difficult to account for if the figure is not Venus.&nbsp;</p>"}],"keys":["d17419de-663c-4828-a1f3-e0078a9fcb6a"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it presents the conclusion that most logically completes the text&rsquo;s discussion about the significance of the cupid found at Pompeii. The text indicates that the cupid is near a statue of a female figure who is fishing, and it goes on to indicate that because Venus is associated with cupids, some scholars believe the female figure to be the goddess Venus. But the text then says that, according to archaeologist Carla Brain, cupids may have also been associated with the activity of fishing, which, if true, would suggest that the mere appearance of a cupid near a female figure engaged in fishing does not indicate with certainty that the figure is Venus (that is, the cupid might be associated with fishing, and the figure might be anyone at all). </p><p>Choice B is incorrect because the text says nothing about how often Venus was depicted fishing in Roman art: it only implies that in certain instances a female figure may or may not be Venus. Choice C is incorrect because Carla Brain&rsquo;s proposed explanation for the presence of the cupids makes no reference to the female figure, and so the possibility that the figure in the artworks is in fact Venus cannot be definitively eliminated. Choice D is incorrect because there is nothing in the text to suggest that the only reasonable way to interpret the figure is as Venus. </p>","parenttemplatename":"OSP-004-INF","parenttemplateid":"","templateclusterid":"bbe3b90c-08e2-4190-b80c-cd067ddfd0f2","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959312,"updateDate":1691007959312}$SATQ$::jsonb, 1691007959312, 1691007959312),
    ($SATQ$5325b3cc$SATQ$, $SATQ$50a97041-1bb7-41a5-ad91-9edb332c7d6b$SATQ$::uuid, $SATQ$5ced755b-6122-45a1-addd-60159296a8c7$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Philadelphia&rsquo;s Black Pearl Chamber Orchestra, founded by Jeri Lynne Johnson, performs classical music, from well-known compositions by Beethoven to contemporary works by Jessie Montgomery. For the orchestra&rsquo;s iConduct! program, Johnson invites community members to learn some basic elements of conducting and then experience conducting the Black Pearl orchestra themselves.</p>$SATQ$, $SATQ$<p>Which choice best states the main idea of the text?</p>$SATQ$, $SATQ$[{"id":"bd5302a1-b0e4-40f7-a7ca-bd575db2e8ed","content":"<p>The Black Pearl orchestra performs music from all over the world but mostly performs music composed by Philadelphians.</p>"},{"id":"c5e0f0f1-94be-4f90-955b-c9c0083453e7","content":"<p>Johnson founded the Black Pearl orchestra to perform classical music by contemporary artist Jessie Montgomery.&nbsp;</p>"},{"id":"62f7c04b-2d40-453a-b45b-270f538d7d17","content":"<p>The Black Pearl orchestra gives community members the chance to both listen to and participate in classical music performance.&nbsp;</p>"},{"id":"ff13b1cf-8a2a-4515-96c3-494b770c76ec","content":"<p>Johnson has community members conduct an orchestra to demonstrate how difficult the task is.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["62f7c04b-2d40-453a-b45b-270f538d7d17"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most accurately states the main idea of the text. The text begins by stating that the Black Pearl orchestra performs classical music, and then goes on to explain that the orchestra offers an iConduct! program. According to the text, this program offers community members the opportunity to learn some basics about conducting and then apply what they learn by conducting the orchestra themselves. Thus, the main idea of the text is that community members can both listen to and participate in a classical music performance. </p><p>Choice A is incorrect. Although the text states that the Black Pearl orchestra is based in Philadelphia, it doesn&rsquo;t indicate that most of the music it plays was composed by Philadelphians. Choice B is incorrect. Although the text does state that Johnson founded the Black Pearl orchestra, this is just a detail and not the main focus of the text. Moreover, while the text does say that the orchestra sometimes plays music by Montgomery, it doesn&rsquo;t assert that the orchestra was founded solely for the purpose of performing Montgomery&rsquo;s work. Choice D is incorrect. Although the text explains that community members are invited to conduct the Black Pearl orchestra after participating in the iConduct! program, the text doesn&rsquo;t indicate that Johnson allows community members to do this for the specific purpose of showing how difficult the task is. </p>$SATQ$, false, 0, $SATQ$OSP-032-CID$SATQ$, $SATQ$$SATQ$, $SATQ$1dfd6c5e-8a2c-4934-b935-7e85a0fcb84d$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"5325b3cc","external_id":"50a97041-1bb7-41a5-ad91-9edb332c7d6b","vaultid":"5ced755b-6122-45a1-addd-60159296a8c7","uId":"34dc3d14-ed11-4eed-94bb-312509705709","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Philadelphia&rsquo;s Black Pearl Chamber Orchestra, founded by Jeri Lynne Johnson, performs classical music, from well-known compositions by Beethoven to contemporary works by Jessie Montgomery. For the orchestra&rsquo;s iConduct! program, Johnson invites community members to learn some basic elements of conducting and then experience conducting the Black Pearl orchestra themselves.</p>","stem":"<p>Which choice best states the main idea of the text?</p>","answerOptions":[{"id":"bd5302a1-b0e4-40f7-a7ca-bd575db2e8ed","content":"<p>The Black Pearl orchestra performs music from all over the world but mostly performs music composed by Philadelphians.</p>"},{"id":"c5e0f0f1-94be-4f90-955b-c9c0083453e7","content":"<p>Johnson founded the Black Pearl orchestra to perform classical music by contemporary artist Jessie Montgomery.&nbsp;</p>"},{"id":"62f7c04b-2d40-453a-b45b-270f538d7d17","content":"<p>The Black Pearl orchestra gives community members the chance to both listen to and participate in classical music performance.&nbsp;</p>"},{"id":"ff13b1cf-8a2a-4515-96c3-494b770c76ec","content":"<p>Johnson has community members conduct an orchestra to demonstrate how difficult the task is.</p>"}],"keys":["62f7c04b-2d40-453a-b45b-270f538d7d17"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most accurately states the main idea of the text. The text begins by stating that the Black Pearl orchestra performs classical music, and then goes on to explain that the orchestra offers an iConduct! program. According to the text, this program offers community members the opportunity to learn some basics about conducting and then apply what they learn by conducting the orchestra themselves. Thus, the main idea of the text is that community members can both listen to and participate in a classical music performance. </p><p>Choice A is incorrect. Although the text states that the Black Pearl orchestra is based in Philadelphia, it doesn&rsquo;t indicate that most of the music it plays was composed by Philadelphians. Choice B is incorrect. Although the text does state that Johnson founded the Black Pearl orchestra, this is just a detail and not the main focus of the text. Moreover, while the text does say that the orchestra sometimes plays music by Montgomery, it doesn&rsquo;t assert that the orchestra was founded solely for the purpose of performing Montgomery&rsquo;s work. Choice D is incorrect. Although the text explains that community members are invited to conduct the Black Pearl orchestra after participating in the iConduct! program, the text doesn&rsquo;t indicate that Johnson allows community members to do this for the specific purpose of showing how difficult the task is. </p>","parenttemplatename":"OSP-032-CID","parenttemplateid":"","templateclusterid":"1dfd6c5e-8a2c-4934-b935-7e85a0fcb84d","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959319,"updateDate":1691007959319}$SATQ$::jsonb, 1691007959319, 1691007959319),
