.1 6\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"224.22088068181816\" x2=\"256.6484375\" y1=\"173.14285714285714\" y2=\"180\"></line><line marker-end=\"url(#marker3)\" marker-start=\"url(#marker3)\" stroke=\"#999\" stroke-width=\"3.5\" x1=\"224.22088068181816\" x2=\"256.6484375\" y1=\"132.57142857142856\" y2=\"127.42857142857142\"></line><line marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\" stroke=\"#000\" stroke-width=\"2.4\" x1=\"256.6484375\" x2=\"289.0759943181818\" y1=\"145.14285714285717\" y2=\"151.42857142857142\"></line><line marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\" stroke=\"#000\" stroke-dasharray=\"9 6\" stroke-width=\"2.4\" x1=\"256.6484375\" x2=\"289.0759943181818\" y1=\"165.7142857142857\" y2=\"165.7142857142857\"></line><line marker-end=\"url(#marker2)\" marker-start=\"url(#marker2)\" stroke=\"#000\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"256.6484375\" x2=\"289.0759943181818\" y1=\"180\" y2=\"180\"></line><line marker-end=\"url(#marker3)\" marker-start=\"url(#marker3)\" stroke=\"#999\" stroke-width=\"3.5\" x1=\"256.6484375\" x2=\"289.0759943181818\" y1=\"127.42857142857142\" y2=\"134.28571428571428\"></line><line marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\" stroke=\"#000\" stroke-width=\"2.4\" x1=\"289.0759943181818\" x2=\"321.5035511363636\" y1=\"151.42857142857142\" y2=\"154.85714285714286\"></line><line marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\" stroke=\"#000\" stroke-dasharray=\"9 6\" stroke-width=\"2.4\" x1=\"289.0759943181818\" x2=\"321.5035511363636\" y1=\"165.7142857142857\" y2=\"163.42857142857144\"></line><line marker-end=\"url(#marker2)\" marker-start=\"url(#marker2)\" stroke=\"#000\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"289.0759943181818\" x2=\"321.5035511363636\" y1=\"180\" y2=\"177.14285714285714\"></line><line marker-end=\"url(#marker3)\" marker-start=\"url(#marker3)\" stroke=\"#999\" stroke-width=\"3.5\" x1=\"289.0759943181818\" x2=\"321.5035511363636\" y1=\"134.28571428571428\" y2=\"140.57142857142858\"></line><line marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\" stroke=\"#000\" stroke-width=\"2.4\" x1=\"321.5035511363636\" x2=\"353.93110795454544\" y1=\"154.85714285714286\" y2=\"143.42857142857144\"></line><line marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\" stroke=\"#000\" stroke-dasharray=\"9 6\" stroke-width=\"2.4\" x1=\"321.5035511363636\" x2=\"353.93110795454544\" y1=\"163.42857142857144\" y2=\"154.85714285714286\"></line><line marker-end=\"url(#marker2)\" marker-start=\"url(#marker2)\" stroke=\"#000\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"321.5035511363636\" x2=\"353.93110795454544\" y1=\"177.14285714285714\" y2=\"170.28571428571428\"></line><line marker-end=\"url(#marker3)\" marker-start=\"url(#marker3)\" stroke=\"#999\" stroke-width=\"3.5\" x1=\"321.5035511363636\" x2=\"353.93110795454544\" y1=\"140.57142857142858\" y2=\"128\"></line><line marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\" stroke=\"#000\" stroke-width=\"2.4\" x1=\"353.93110795454544\" x2=\"386.35866477272725\" y1=\"143.42857142857144\" y2=\"131.42857142857144\"></line><line marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\" stroke=\"#000\" stroke-dasharray=\"9 6\" stroke-width=\"2.4\" x1=\"353.93110795454544\" x2=\"386.35866477272725\" y1=\"154.85714285714286\" y2=\"146.85714285714283\"></line><line marker-end=\"url(#marker2)\" marker-start=\"url(#marker2)\" stroke=\"#000\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"353.93110795454544\" x2=\"386.35866477272725\" y1=\"170.28571428571428\" y2=\"159.42857142857144\"></line><line marker-end=\"url(#marker3)\" marker-start=\"url(#marker3)\" stroke=\"#999\" stroke-width=\"3.5\" x1=\"353.93110795454544\" x2=\"386.35866477272725\" y1=\"128\" y2=\"117.14285714285714\"></line><line marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\" stroke=\"#000\" stroke-width=\"2.4\" x1=\"386.35866477272725\" x2=\"418.78622159090907\" y1=\"131.42857142857144\" y2=\"112.57142857142858\"></line><line marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\" stroke=\"#000\" stroke-dasharray=\"9 6\" stroke-width=\"2.4\" x1=\"386.35866477272725\" x2=\"418.78622159090907\" y1=\"146.85714285714283\" y2=\"142.85714285714286\"></line><line marker-end=\"url(#marker2)\" marker-start=\"url(#marker2)\" stroke=\"#000\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"386.35866477272725\" x2=\"418.78622159090907\" y1=\"159.42857142857144\" y2=\"152.57142857142856\"></line><line marker-end=\"url(#marker3)\" marker-start=\"url(#marker3)\" stroke=\"#999\" stroke-width=\"3.5\" x1=\"386.35866477272725\" x2=\"418.78622159090907\" y1=\"117.14285714285714\" y2=\"97.14285714285717\"></line></g></svg></figure></p>\n<p>A sociology student is reading an essay on the median age of first marriage in Western countries throughout the twentieth century. The author of the essay cites factors common to these countries that the author believes caused an increase in the median age of first marriage, such as new technologies that shortened the time needed for domestic chores, making two-person households less necessary and living alone more viable. The student asserts that beyond these factors there must be additional ones specific to particular Western countries that influenced the increase of age at first marriage.</p>","stem":"<p>Which choice most effectively uses data from the graph that support the student&rsquo;s assertion?</p>","answerOptions":[{"id":"49f8366f-e47d-4de6-a9ee-3fa5c82a3d4d","content":"<p>Between 1970 and 2000, the median age of first marriage rose more sharply for men in England and Wales than it did for men in the United States.</p>"},{"id":"5cb8a612-af28-4ae0-8255-f74a2e34ac05","content":"<p>In England and Wales, the median age of first marriage was consistently higher for men than for women between 1900 and 2000, but this was not always the case in the United States.</p>"},{"id":"8eb63dff-5faf-4cb3-84a2-31f750d06dc1","content":"<p>The median age of first marriage for men in England and Wales was lower in 1970 than in 1950 or 1990.</p>"},{"id":"0ab0c6a9-e1bd-49c3-9b0f-4507baae7622","content":"<p>Between 1900 and 2000, the median age of first marriage for women in England and Wales was consistently higher than for women in the United States, as was the case for men.</p>"}],"keys":["49f8366f-e47d-4de6-a9ee-3fa5c82a3d4d"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The student concluded that country-specific factors influence changes to median age of first marriage. This choice describes a time period when the rate of change differed between countries, suggesting that country-specific factors may have played a role in these changes. </p><p>Choice B is incorrect. This choice misreads the graph. The median age of first marriage was consistently higher for men than for women in the United States during the time period depicted. Choice C is incorrect. The student concluded that country-specific factors influence changes to median age of first marriage. However, this choice doesn&rsquo;t provide any contrasts between countries and thus doesn&rsquo;t support the idea of country-specific factors influencing median age of first marriage. Choice D is incorrect. The students&rsquo; conclusion is about changes that occurred during the 20th century. This choice provides broad information about the century as a whole, so it doesn&rsquo;t give insight into how median age at first marriage changed over time. </p>","parenttemplatename":"OSP-KA-QUA-H007","parenttemplateid":"","templateclusterid":"0e803013-4612-408e-9278-eeb0bee77cb6","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959369,"updateDate":1691007959369}$SATQ$::jsonb, 1691007959369, 1691007959369),
    ($SATQ$54057e3f$SATQ$, $SATQ$27983d00-7eb0-40fd-9ecc-733f78d21ce9$SATQ$::uuid, $SATQ$346fae91-b33d-46c8-b567-9773b68af3c9$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Although military veterans make up a small proportion of the total population of the United States, they occupy a significantly higher proportion of the jobs in the civilian government. One possible explanation for this disproportionate representation is that military service familiarizes people with certain organizational structures that are also reflected in the civilian government bureaucracy, and this familiarity thus <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"aef526ca-4321-44b8-a950-eb8e7be508a4","content":"<p>makes civilian government jobs especially appealing to military veterans.</p>"},{"id":"052d4329-9ad0-475c-8793-cfd9d462f127","content":"<p>alters the typical relationship between military service and subsequent career preferences.</p>"},{"id":"f60391e4-1b65-465c-85d6-db0884e70d45","content":"<p>encourages nonveterans applying for civilian government jobs to consider military service instead.</p>"},{"id":"0d053de1-c6a3-44c7-b7b4-5a085af6ecb6","content":"<p>increases the number of civilian government jobs that require some amount of military experience to perform.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["aef526ca-4321-44b8-a950-eb8e7be508a4"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it presents the conclusion that most logically follows from the text&rsquo;s discussion of military veterans working in civilian government jobs in the United States. The text indicates that the proportion of military veterans working in civilian government jobs is considerably higher than the proportion of military veterans in the population as a whole. The text also notes that the unusually high representation of military veterans in these jobs may be a result of the organizational structures&nbsp; shared by civilian government entities and the military. Hence, it&rsquo;s reasonable to infer that it&rsquo;s the familiarity of the structures of civilian government that makes jobs there particularly attractive to military veterans.&nbsp;</p><p>Choice B is incorrect because the text doesn&rsquo;t address what a typical relationship between military service and later career preferences would be, and there&rsquo;s no indication that it&rsquo;s atypical for veterans to work in civilian government jobs after they&rsquo;ve left the military. On the contrary, the text suggests that many military veterans are drawn to such jobs. Choice C is incorrect because the text is focused on the high representation of military veterans in civilian government jobs and doesn&rsquo;t address nonveterans or their possible interest in military service.&nbsp;Choice D is incorrect because the text conveys that military veterans may be particularly interested in civilian government jobs due to the familiarity of organizational structures that are already in place, but there&rsquo;s no reason to think that this interest would mean that more civilian government jobs will start to require military experience. </p>$SATQ$, false, 0, $SATQ$OSP-008-INF$SATQ$, $SATQ$$SATQ$, $SATQ$3882fda8-783e-4606-8f4a-a7b35449267a$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"54057e3f","external_id":"27983d00-7eb0-40fd-9ecc-733f78d21ce9","vaultid":"346fae91-b33d-46c8-b567-9773b68af3c9","uId":"48a0cec6-13ff-4dd7-b2ec-fb13ab6ea011","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Although military veterans make up a small proportion of the total population of the United States, they occupy a significantly higher proportion of the jobs in the civilian government. One possible explanation for this disproportionate representation is that military service familiarizes people with certain organizational structures that are also reflected in the civilian government bureaucracy, and this familiarity thus <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"aef526ca-4321-44b8-a950-eb8e7be508a4","content":"<p>makes civilian government jobs especially appealing to military veterans.</p>"},{"id":"052d4329-9ad0-475c-8793-cfd9d462f127","content":"<p>alters the typical relationship between military service and subsequent career preferences.</p>"},{"id":"f60391e4-1b65-465c-85d6-db0884e70d45","content":"<p>encourages nonveterans applying for civilian government jobs to consider military service instead.</p>"},{"id":"0d053de1-c6a3-44c7-b7b4-5a085af6ecb6","content":"<p>increases the number of civilian government jobs that require some amount of military experience to perform.</p>"}],"keys":["aef526ca-4321-44b8-a950-eb8e7be508a4"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it presents the conclusion that most logically follows from the text&rsquo;s discussion of military veterans working in civilian government jobs in the United States. The text indicates that the proportion of military veterans working in civilian government jobs is considerably higher than the proportion of military veterans in the population as a whole. The text also notes that the unusually high representation of military veterans in these jobs may be a result of the organizational structures&nbsp; shared by civilian government entities and the military. Hence, it&rsquo;s reasonable to infer that it&rsquo;s the familiarity of the structures of civilian government that makes jobs there particularly attractive to military veterans.&nbsp;</p><p>Choice B is incorrect because the text doesn&rsquo;t address what a typical relationship between military service and later career preferences would be, and there&rsquo;s no indication that it&rsquo;s atypical for veterans to work in civilian government jobs after they&rsquo;ve left the military. On the contrary, the text suggests that many military veterans are drawn to such jobs. Choice C is incorrect because the text is focused on the high representation of military veterans in civilian government jobs and doesn&rsquo;t address nonveterans or their possible interest in military service.&nbsp;Choice D is incorrect because the text conveys that military veterans may be particularly interested in civilian government jobs due to the familiarity of organizational structures that are already in place, but there&rsquo;s no reason to think that this interest would mean that more civilian government jobs will start to require military experience. </p>","parenttemplatename":"OSP-008-INF","parenttemplateid":"","templateclusterid":"3882fda8-783e-4606-8f4a-a7b35449267a","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959313,"updateDate":1691007959313}$SATQ$::jsonb, 1691007959313, 1691007959313),
    ($SATQ$5432d1de$SATQ$, $SATQ$a01408ec-f674-4193-a639-57cc6064b5bd$SATQ$::uuid, $SATQ$8678044f-82b2-46d2-9926-de37491caabb$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>It&rsquo;s common for jazz musicians and fans to refer to certain songs as having &ldquo;swing,&rdquo; indicating that the songs provoke a strong feeling, like the impulse to tap one&rsquo;s foot or dance. The exact acoustic properties that give a song swing, however, have long been thought to be undefinable. To investigate swing, a team led by physicist Corentin Nelias delayed the downbeats and synchronized the offbeats in jazz piano solos and asked jazz musicians to compare the intensity of swing in each modified piece with the intensity of swing in the original piece. They found that participants were more than seven times likelier to characterize the modified songs as having swing than to characterize the original versions as having swing, suggesting that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"2ed2afa6-cebd-45fc-adc0-2cc4559b9862","content":"<p>synchronized offbeats tend to give a song swing regardless of whether downbeats are delayed.</p>"},{"id":"42900b99-fc69-4c0a-acef-204377700061","content":"<p>the acoustic properties that give a song swing are not easy for jazz musicians to manipulate.</p>"},{"id":"f7ba985a-ca30-4222-8b00-24d71f1fcca8","content":"<p>jazz songs that feature the piano are more likely to have swing than are jazz songs that do not feature the piano.</p>"},{"id":"02109fe3-fbd4-40d1-8346-a9ef9a1f9691","content":"<p>the timing of downbeats and offbeats may play a crucial role in giving a song swing.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["02109fe3-fbd4-40d1-8346-a9ef9a1f9691"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The passage tells us that participants were &ldquo;more than seven times likelier to characterize the modified songs as having swing than to characterize the original versions as having swing.&rdquo; Because the modified songs had been changed by altering the timing of the downbeats and offbeats, this suggests that the timing of downbeats and offbeats may play a crucial role in giving a song swing. </p><p>Choice A is incorrect. Although the passage mentions that the researchers &ldquo;synchronized the offbeats&rdquo; in the modified songs, they also &ldquo;delayed the downbeats&rdquo; in those songs. Because we can&rsquo;t disentangle whether it was the synchronized offbeats, the delayed downbeats, or the combination of both that increased the song&rsquo;s swing, we don&rsquo;t have enough information to make this inference. Choice B is incorrect. The passage doesn&rsquo;t mention whether or not it&rsquo;s difficult for a jazz musician to give a song swing, so there&rsquo;s no basis for this inference. Choice C is incorrect. The passage doesn&rsquo;t compare jazz songs that feature piano to those that don&rsquo;t, so there&rsquo;s no basis for this inference. </p>$SATQ$, false, 0, $SATQ$OSP-KA-INF-M006$SATQ$, $SATQ$$SATQ$, $SATQ$a1fc525f-8c2f-4431-8efb-314a47d305ed$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"5432d1de","external_id":"a01408ec-f674-4193-a639-57cc6064b5bd","vaultid":"8678044f-82b2-46d2-9926-de37491caabb","uId":"6a3a94fc-34a3-48e9-8f77-d52963c4f8b3","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>It&rsquo;s common for jazz musicians and fans to refer to certain songs as having &ldquo;swing,&rdquo; indicating that the songs provoke a strong feeling, like the impulse to tap one&rsquo;s foot or dance. The exact acoustic properties that give a song swing, however, have long been thought to be undefinable. To investigate swing, a team led by physicist Corentin Nelias delayed the downbeats and synchronized the offbeats in jazz piano solos and asked jazz musicians to compare the intensity of swing in each modified piece with the intensity of swing in the original piece. They found that participants were more than seven times likelier to characterize the modified songs as having swing than to characterize the original versions as having swing, suggesting that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"2ed2afa6-cebd-45fc-adc0-2cc4559b9862","content":"<p>synchronized offbeats tend to give a song swing regardless of whether downbeats are delayed.</p>"},{"id":"42900b99-fc69-4c0a-acef-204377700061","content":"<p>the acoustic properties that give a song swing are not easy for jazz musicians to manipulate.</p>"},{"id":"f7ba985a-ca30-4222-8b00-24d71f1fcca8","content":"<p>jazz songs that feature the piano are more likely to have swing than are jazz songs that do not feature the piano.</p>"},{"id":"02109fe3-fbd4-40d1-8346-a9ef9a1f9691","content":"<p>the timing of downbeats and offbeats may play a crucial role in giving a song swing.&nbsp;</p>"}],"keys":["02109fe3-fbd4-40d1-8346-a9ef9a1f9691"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The passage tells us that participants were &ldquo;more than seven times likelier to characterize the modified songs as having swing than to characterize the original versions as having swing.&rdquo; Because the modified songs had been changed by altering the timing of the downbeats and offbeats, this suggests that the timing of downbeats and offbeats may play a crucial role in giving a song swing. </p><p>Choice A is incorrect. Although the passage mentions that the researchers &ldquo;synchronized the offbeats&rdquo; in the modified songs, they also &ldquo;delayed the downbeats&rdquo; in those songs. Because we can&rsquo;t disentangle whether it was the synchronized offbeats, the delayed downbeats, or the combination of both that increased the song&rsquo;s swing, we don&rsquo;t have enough information to make this inference. Choice B is incorrect. The passage doesn&rsquo;t mention whether or not it&rsquo;s difficult for a jazz musician to give a song swing, so there&rsquo;s no basis for this inference. Choice C is incorrect. The passage doesn&rsquo;t compare jazz songs that feature piano to those that don&rsquo;t, so there&rsquo;s no basis for this inference. </p>","parenttemplatename":"OSP-KA-INF-M006","parenttemplateid":"","templateclusterid":"a1fc525f-8c2f-4431-8efb-314a47d305ed","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959368,"updateDate":1691007959368}$SATQ$::jsonb, 1691007959368, 1691007959368),
    ($SATQ$54be8f96$SATQ$, $SATQ$7d889d5e-6ff0-4c2b-a1b2-9b0d56817fea$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Properties of TRAPPIST-1 Exoplanets Compared to Earth’s Properties</p></caption><thead><tr><th scope="col" style="text-align: center;vertical-align: bottom;">Planet</th><th scope="col" style="text-align: center;vertical-align: bottom;">Orbital period (days)</th><th scope="col" style="text-align: center;vertical-align: bottom;">Planet radius (Earth radii)</th></tr></thead><tbody><tr><th scope="row" style="text-align: left;">Earth</th><td style="text-align: center;">365.26</td><td style="text-align: center;">1</td></tr><tr><th scope="row" style="text-align: left;">TRAPPIST-1b</th><td style="text-align: center;">1.51</td><td style="text-align: center;">1.09</td></tr><tr><th scope="row" style="text-align: left;">TRAPPIST-1d</th><td style="text-align: center;">4.05</td><td style="text-align: center;">0.77</td></tr><tr><th scope="row" style="text-align: left;">TRAPPIST-1e</th><td style="text-align: center;">6.1</td><td style="text-align: center;">0.92</td></tr><tr><th scope="row" style="text-align: left;">TRAPPIST-1f</th><td style="text-align: center;">9.21</td><td style="text-align: center;">1.04</td></tr></tbody></table></figure></p>
<p>TRAPPIST-1 is a planetary system with a central red dwarf star and several Earth-sized exoplanets. Each planet in this system is so close in orbit to the star that the gravitational forces acting between the planet and the star cause the planet&rsquo;s rotational period around its axis and orbital period around the star to be equal. For example, the orbital period of TRAPPIST-1e is <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most effectively uses data from the table to complete the example?</p>$SATQ$, $SATQ$[{"id":"4bf7a4ee-15b7-474e-87ac-e3271bbe182e","content":"<p>1.51 days, which is the shortest rotational period of any of the TRAPPIST planets.</p>"},{"id":"a230b45c-3d2c-4ffc-8823-7c943abf838d","content":"<p>6.1 days, and its rotational period is also 6.1 days.</p>"},{"id":"400e73a8-fc7c-4331-8797-6af8fae2f415","content":"<p>9.21 days, which is the same as the rotational period of TRAPPIST-1f.</p>"},{"id":"8100e6b1-95b4-4018-8683-e8f08fa656c6","content":"<p>6.1 days, and its rotational period is 0.92 days.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["a230b45c-3d2c-4ffc-8823-7c943abf838d"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it correctly uses data from the table to illustrate the relationship between orbital and rotational periods described in the text. For Earth and each of four TRAPPIST-1 exoplanets, the table provides the orbital period and radius (in relation to the radius of Earth). The text explains that for each TRAPPIST-1 exoplanet, gravitational forces cause the rotational period (how long the planet takes to spin once on its axis) to equal the orbital period (how long the planet takes to orbit the star). According to the table, TRAPPIST-1e has an orbital period of 6.1 days. Since the text states that the orbital and rotational periods are equal for these planets, TRAPPIST-1e&rsquo;s rotational period must also be 6.1 days.</p><p>Choice A is incorrect because the table shows that TRAPPIST-1e has an orbital period (and thus a rotational period) of 6.1 days, not 1.51 days, which is the orbital period (and thus the rotational period) of TRAPPIST-1b. Furthermore, comparing the length of TRAPPIST-1e&rsquo;s rotational period to those of the other exoplanets would not logically complete the example, which should illustrate how the orbital and rotational periods of a planet in TRAPPIST-1 are the same length. Choice C is incorrect because the table shows that TRAPPIST-1e has an orbital period (and thus a rotational period) of 6.1 days, not 9.21 days, which the table shows is the orbital period (and thus rotational period) of TRAPPIST-1f. Additionally, comparing the rotational periods of two exoplanets would not logically complete the example, which should illustrate how the orbital and rotational periods of a planet in TRAPPIST-1 are the same length. Choice D is incorrect because although it correctly identifies TRAPPIST-1e&rsquo;s orbital period as 6.1 days, it incorrectly states that its rotational period is 0.92 days. This contradicts the text&rsquo;s statement that the orbital and rotational periods are equal for TRAPPIST-1 exoplanets. The value 0.92 actually represents TRAPPIST-1e&rsquo;s radius in relation to Earth&rsquo;s radius, not its rotational period.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"54be8f96","external_id":"7d889d5e-6ff0-4c2b-a1b2-9b0d56817fea","vaultid":null,"uId":"fe9dd2c5-1980-4ee4-a249-651e98c52663","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Properties of TRAPPIST-1 Exoplanets Compared to Earth’s Properties</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Planet</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Orbital period (days)</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Planet radius (Earth radii)</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: left;\">Earth</th><td style=\"text-align: center;\">365.26</td><td style=\"text-align: center;\">1</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">TRAPPIST-1b</th><td style=\"text-align: center;\">1.51</td><td style=\"text-align: center;\">1.09</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">TRAPPIST-1d</th><td style=\"text-align: center;\">4.05</td><td style=\"text-align: center;\">0.77</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">TRAPPIST-1e</th><td style=\"text-align: center;\">6.1</td><td style=\"text-align: center;\">0.92</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">TRAPPIST-1f</th><td style=\"text-align: center;\">9.21</td><td style=\"text-align: center;\">1.04</td></tr></tbody></table></figure></p>\n<p>TRAPPIST-1 is a planetary system with a central red dwarf star and several Earth-sized exoplanets. Each planet in this system is so close in orbit to the star that the gravitational forces acting between the planet and the star cause the planet&rsquo;s rotational period around its axis and orbital period around the star to be equal. For example, the orbital period of TRAPPIST-1e is <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most effectively uses data from the table to complete the example?</p>","answerOptions":[{"id":"4bf7a4ee-15b7-474e-87ac-e3271bbe182e","content":"<p>1.51 days, which is the shortest rotational period of any of the TRAPPIST planets.</p>"},{"id":"a230b45c-3d2c-4ffc-8823-7c943abf838d","content":"<p>6.1 days, and its rotational period is also 6.1 days.</p>"},{"id":"400e73a8-fc7c-4331-8797-6af8fae2f415","content":"<p>9.21 days, which is the same as the rotational period of TRAPPIST-1f.</p>"},{"id":"8100e6b1-95b4-4018-8683-e8f08fa656c6","content":"<p>6.1 days, and its rotational period is 0.92 days.</p>"}],"keys":["a230b45c-3d2c-4ffc-8823-7c943abf838d"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it correctly uses data from the table to illustrate the relationship between orbital and rotational periods described in the text. For Earth and each of four TRAPPIST-1 exoplanets, the table provides the orbital period and radius (in relation to the radius of Earth). The text explains that for each TRAPPIST-1 exoplanet, gravitational forces cause the rotational period (how long the planet takes to spin once on its axis) to equal the orbital period (how long the planet takes to orbit the star). According to the table, TRAPPIST-1e has an orbital period of 6.1 days. Since the text states that the orbital and rotational periods are equal for these planets, TRAPPIST-1e&rsquo;s rotational period must also be 6.1 days.</p><p>Choice A is incorrect because the table shows that TRAPPIST-1e has an orbital period (and thus a rotational period) of 6.1 days, not 1.51 days, which is the orbital period (and thus the rotational period) of TRAPPIST-1b. Furthermore, comparing the length of TRAPPIST-1e&rsquo;s rotational period to those of the other exoplanets would not logically complete the example, which should illustrate how the orbital and rotational periods of a planet in TRAPPIST-1 are the same length. Choice C is incorrect because the table shows that TRAPPIST-1e has an orbital period (and thus a rotational period) of 6.1 days, not 9.21 days, which the table shows is the orbital period (and thus rotational period) of TRAPPIST-1f. Additionally, comparing the rotational periods of two exoplanets would not logically complete the example, which should illustrate how the orbital and rotational periods of a planet in TRAPPIST-1 are the same length. Choice D is incorrect because although it correctly identifies TRAPPIST-1e&rsquo;s orbital period as 6.1 days, it incorrectly states that its rotational period is 0.92 days. This contradicts the text&rsquo;s statement that the orbital and rotational periods are equal for TRAPPIST-1 exoplanets. The value 0.92 actually represents TRAPPIST-1e&rsquo;s radius in relation to Earth&rsquo;s radius, not its rotational period.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771169,"updateDate":1776362771169}$SATQ$::jsonb, 1776362771169, 1776362771169),
    ($SATQ$55688b3c$SATQ$, $SATQ$6efd0d81-35c8-49da-88a2-390c63a8fd80$SATQ$::uuid, $SATQ$f3cb4419-7099-4d57-ac27-f5b3fb7c69f4$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Dutch painters in the sixteenth and seventeenth centuries often showed tables filled with large wheels of cheese or carved shards of butter. Some art historians, noting that dairy products were a major component of the Dutch diet, interpret these depictions as reflections of everyday Dutch eating habits. However, a group of researchers recently reviewed hundreds of food-related paintings and found that lemons&mdash;which could only be acquired in the Netherlands at great cost, since they had to be imported from warmer climates&mdash;feature in Dutch paintings of the period more than three times as frequently as dairy products do, thereby casting doubt on the idea that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"67e30fc3-34e5-4eea-964a-60fd0fe843bd","content":"<p>dairy products were a more significant component of the Dutch diet of the period than lemons were.</p>"},{"id":"33f148d1-331d-4677-8d01-2781b3ca3177","content":"<p>food was a more popular subject among Dutch painters than it was among painters from other countries at the time.&nbsp;</p>"},{"id":"4adec29b-4616-4dde-94bc-786eb2ed5eca","content":"<p>depictions of food in Dutch paintings of the period should be taken as realistic representations of Dutch eating habits.</p>"},{"id":"1c847339-581b-447e-b81e-f38db44647b7","content":"<p>Dutch painters of the period may have depicted foods for symbolic reasons rather than to show what Dutch people typically ate.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["4adec29b-4616-4dde-94bc-786eb2ed5eca"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The text tells us that lemons&mdash;an expensive imported product&mdash;feature in Dutch paintings of the period more frequently than dairy products do. Since it&rsquo;s unlikely lemons were eaten more often than dairy, this fact casts doubt on the theory that these paintings realistically depicted Dutch diets.</p><p>Choice A is incorrect. In fact, the text suggests the opposite: it says that dairy products were a "major component of the Dutch diet," while lemons were an expensive import item, so we can infer that lemons were eaten much more rarely than dairy products. Choice B is incorrect. The passage doesn&rsquo;t mention painters from other countries, so there&rsquo;s no basis to make this inference. Choice D is incorrect. In fact, the text suggests that Dutch painters do have reasons for depicting foods other than to show what Dutch people typically ate. For example, lemons in a painting could indicate wealth or prosperity.</p>$SATQ$, false, 0, $SATQ$OSP-KA-INF-M005$SATQ$, $SATQ$$SATQ$, $SATQ$8b2c96ae-47bb-4486-83bb-4c9220f11f08$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"55688b3c","external_id":"6efd0d81-35c8-49da-88a2-390c63a8fd80","vaultid":"f3cb4419-7099-4d57-ac27-f5b3fb7c69f4","uId":"5baf9aa9-b68f-4d08-95c3-fe202928093e","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Dutch painters in the sixteenth and seventeenth centuries often showed tables filled with large wheels of cheese or carved shards of butter. Some art historians, noting that dairy products were a major component of the Dutch diet, interpret these depictions as reflections of everyday Dutch eating habits. However, a group of researchers recently reviewed hundreds of food-related paintings and found that lemons&mdash;which could only be acquired in the Netherlands at great cost, since they had to be imported from warmer climates&mdash;feature in Dutch paintings of the period more than three times as frequently as dairy products do, thereby casting doubt on the idea that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"67e30fc3-34e5-4eea-964a-60fd0fe843bd","content":"<p>dairy products were a more significant component of the Dutch diet of the period than lemons were.</p>"},{"id":"33f148d1-331d-4677-8d01-2781b3ca3177","content":"<p>food was a more popular subject among Dutch painters than it was among painters from other countries at the time.&nbsp;</p>"},{"id":"4adec29b-4616-4dde-94bc-786eb2ed5eca","content":"<p>depictions of food in Dutch paintings of the period should be taken as realistic representations of Dutch eating habits.</p>"},{"id":"1c847339-581b-447e-b81e-f38db44647b7","content":"<p>Dutch painters of the period may have depicted foods for symbolic reasons rather than to show what Dutch people typically ate.</p>"}],"keys":["4adec29b-4616-4dde-94bc-786eb2ed5eca"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The text tells us that lemons&mdash;an expensive imported product&mdash;feature in Dutch paintings of the period more frequently than dairy products do. Since it&rsquo;s unlikely lemons were eaten more often than dairy, this fact casts doubt on the theory that these paintings realistically depicted Dutch diets.</p><p>Choice A is incorrect. In fact, the text suggests the opposite: it says that dairy products were a \"major component of the Dutch diet,\" while lemons were an expensive import item, so we can infer that lemons were eaten much more rarely than dairy products. Choice B is incorrect. The passage doesn&rsquo;t mention painters from other countries, so there&rsquo;s no basis to make this inference. Choice D is incorrect. In fact, the text suggests that Dutch painters do have reasons for depicting foods other than to show what Dutch people typically ate. For example, lemons in a painting could indicate wealth or prosperity.</p>","parenttemplatename":"OSP-KA-INF-M005","parenttemplateid":"","templateclusterid":"8b2c96ae-47bb-4486-83bb-4c9220f11f08","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959368,"updateDate":1691007959368}$SATQ$::jsonb, 1691007959368, 1691007959368),
    ($SATQ$55df0275$SATQ$, $SATQ$c3d04fab-85b3-4607-9920-c2490bdcc643$SATQ$::uuid, $SATQ$6e92c8dc-777a-47be-9e9f-24bc986531b3$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Ablation Rates for Three Elements in Cosmic Dust, by Dust Source</p></caption><thead><tr><th scope="col" style="text-align: center; vertical-align: bottom;">Element</th><th scope="col" style="text-align: center; vertical-align: bottom;">SPC</th><th scope="col" style="text-align: center; vertical-align: bottom;">AST</th><th scope="col" style="text-align: center; vertical-align: bottom;">HTC</th><th scope="col" style="text-align: center; vertical-align: bottom;">OCC</th></tr></thead><tbody><tr><th scope="row" style="text-align: left;">iron</th><td style="text-align: center;">20%</td><td style="text-align: center;">28%</td><td style="text-align: center;">90%</td><td style="text-align: center;">98%</td></tr><tr><th scope="row" style="text-align: left;">potassium</th><td style="text-align: center;">44%</td><td style="text-align: center;">74%</td><td style="text-align: center;">97%</td><td style="text-align: center;">100%</td></tr><tr><th scope="row" style="text-align: left;">sodium</th><td style="text-align: center;">45%</td><td style="text-align: center;">75%</td><td style="text-align: center;">99%</td><td style="text-align: center;">100%</td></tr></tbody></table></figure></p>
<p>Earth&rsquo;s atmosphere is bombarded by cosmic dust originating from several sources: short-period comets (SPCs), particles from the asteroid belt (ASTs), Halley-type comets (HTCs), and Oort cloud comets (OCCs). Some of the dust&rsquo;s material vaporizes in the atmosphere in a process called ablation, and the faster the particles move, the higher the rate of ablation. Astrophysicist Juan Diego Carrillo-S&aacute;nchez led a team that calculated average ablation rates for elements in the dust (such as iron and potassium) and showed that material in slower-moving SPC or AST dust has a lower rate than the same material in faster-moving HTC or OCC dust. For example, whereas the average ablation rate for iron from AST dust is 28%, the average rate for <span aria-hidden="true">______</span><span class="sr-only">blank</span>&nbsp;</p>$SATQ$, $SATQ$<p>Which choice most effectively uses data from the table to complete the example?</p>$SATQ$, $SATQ$[{"id":"49e98929-1bb2-4abe-add6-b390b89d4c2e","content":"<p>iron from SPC dust is 20%.</p>"},{"id":"a466b8fa-5d21-4dc4-b6fc-8c8635361458","content":"<p>sodium from OCC dust is 100%.</p>"},{"id":"64e0d244-872b-4447-bdff-ad4bb82ea6aa","content":"<p>iron from HTC dust is 90%.</p>"},{"id":"5504723b-0429-4b45-821d-92f4fddec050","content":"<p>sodium from AST dust is 75%.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["64e0d244-872b-4447-bdff-ad4bb82ea6aa"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most effectively completes the example regarding the ablation rate of iron. The table shows the ablation rates for three elements&mdash;iron, potassium, and sodium&mdash;found in cosmic dust that comes from one of four sources. The text says that the ablation rate for a given element in slower-moving SPC and AST dust was lower than the ablation rate for that same element in faster-moving HTC or OCC dust. The text then presents the first part of an example of this pattern, describing an ablation rate of 28% for iron in AST dust. The information that iron from HTC dust had an ablation rate of 90% is therefore the most effective way to complete this example&mdash;the comparison of a relatively low ablation rate for iron in slower-moving AST dust with a relatively high ablation rate for iron in faster-moving HTC dust illustrates the tendency of ablation rates for a given element to be lower in slower-moving dust than in faster-moving dust. </p><p>Choice A is incorrect because the text indicates that SPC dust, like AST dust, moves relatively slowly; a comparison of the ablation rates of iron from two slower-moving dust sources could not be an example of the difference between ablation rates in slower-moving dust and faster-moving dust, which is the pattern that the example is supposed to illustrate. Choice B is incorrect because the example in the text is supposed to illustrate the difference in the ablation rates of the same element from slower-moving dust and faster-moving dust, and the first part of the example provides data about the ablation rate of iron, which means the second part of the example must also be about the ablation rate of iron, not the ablation rate of sodium. Choice D is incorrect because the example in the text is supposed to illustrate the difference in the ablation rates of the same element from slower-moving dust and faster-moving dust, and the first part of the example provides data about the ablation rate of iron, which means the second part of the example must also be about the ablation rate of iron, not the ablation rate of sodium. Additionally, any ablation rate from AST dust would be ineffective in this example since AST dust is referenced in the first part of the example and thus additional data focused on AST dust would not illustrate a variation across dust types. </p>$SATQ$, false, 0, $SATQ$OSP-512-QUA$SATQ$, $SATQ$$SATQ$, $SATQ$49762729-5f16-4572-9c30-0eef57f09861$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"55df0275","external_id":"c3d04fab-85b3-4607-9920-c2490bdcc643","vaultid":"6e92c8dc-777a-47be-9e9f-24bc986531b3","uId":"7939ed6d-0de7-4f86-b191-1d1abac61f8b","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Ablation Rates for Three Elements in Cosmic Dust, by Dust Source</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Element</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">SPC</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">AST</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">HTC</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">OCC</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: left;\">iron</th><td style=\"text-align: center;\">20%</td><td style=\"text-align: center;\">28%</td><td style=\"text-align: center;\">90%</td><td style=\"text-align: center;\">98%</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">potassium</th><td style=\"text-align: center;\">44%</td><td style=\"text-align: center;\">74%</td><td style=\"text-align: center;\">97%</td><td style=\"text-align: center;\">100%</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">sodium</th><td style=\"text-align: center;\">45%</td><td style=\"text-align: center;\">75%</td><td style=\"text-align: center;\">99%</td><td style=\"text-align: center;\">100%</td></tr></tbody></table></figure></p>\n<p>Earth&rsquo;s atmosphere is bombarded by cosmic dust originating from several sources: short-period comets (SPCs), particles from the asteroid belt (ASTs), Halley-type comets (HTCs), and Oort cloud comets (OCCs). Some of the dust&rsquo;s material vaporizes in the atmosphere in a process called ablation, and the faster the particles move, the higher the rate of ablation. Astrophysicist Juan Diego Carrillo-S&aacute;nchez led a team that calculated average ablation rates for elements in the dust (such as iron and potassium) and showed that material in slower-moving SPC or AST dust has a lower rate than the same material in faster-moving HTC or OCC dust. For example, whereas the average ablation rate for iron from AST dust is 28%, the average rate for <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span>&nbsp;</p>","stem":"<p>Which choice most effectively uses data from the table to complete the example?</p>","answerOptions":[{"id":"49e98929-1bb2-4abe-add6-b390b89d4c2e","content":"<p>iron from SPC dust is 20%.</p>"},{"id":"a466b8fa-5d21-4dc4-b6fc-8c8635361458","content":"<p>sodium from OCC dust is 100%.</p>"},{"id":"64e0d244-872b-4447-bdff-ad4bb82ea6aa","content":"<p>iron from HTC dust is 90%.</p>"},{"id":"5504723b-0429-4b45-821d-92f4fddec050","content":"<p>sodium from AST dust is 75%.</p>"}],"keys":["64e0d244-872b-4447-bdff-ad4bb82ea6aa"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most effectively completes the example regarding the ablation rate of iron. The table shows the ablation rates for three elements&mdash;iron, potassium, and sodium&mdash;found in cosmic dust that comes from one of four sources. The text says that the ablation rate for a given element in slower-moving SPC and AST dust was lower than the ablation rate for that same element in faster-moving HTC or OCC dust. The text then presents the first part of an example of this pattern, describing an ablation rate of 28% for iron in AST dust. The information that iron from HTC dust had an ablation rate of 90% is therefore the most effective way to complete this example&mdash;the comparison of a relatively low ablation rate for iron in slower-moving AST dust with a relatively high ablation rate for iron in faster-moving HTC dust illustrates the tendency of ablation rates for a given element to be lower in slower-moving dust than in faster-moving dust. </p><p>Choice A is incorrect because the text indicates that SPC dust, like AST dust, moves relatively slowly; a comparison of the ablation rates of iron from two slower-moving dust sources could not be an example of the difference between ablation rates in slower-moving dust and faster-moving dust, which is the pattern that the example is supposed to illustrate. Choice B is incorrect because the example in the text is supposed to illustrate the difference in the ablation rates of the same element from slower-moving dust and faster-moving dust, and the first part of the example provides data about the ablation rate of iron, which means the second part of the example must also be about the ablation rate of iron, not the ablation rate of sodium. Choice D is incorrect because the example in the text is supposed to illustrate the difference in the ablation rates of the same element from slower-moving dust and faster-moving dust, and the first part of the example provides data about the ablation rate of iron, which means the second part of the example must also be about the ablation rate of iron, not the ablation rate of sodium. Additionally, any ablation rate from AST dust would be ineffective in this example since AST dust is referenced in the first part of the example and thus additional data focused on AST dust would not illustrate a variation across dust types. </p>","parenttemplatename":"OSP-512-QUA","parenttemplateid":"","templateclusterid":"49762729-5f16-4572-9c30-0eef57f09861","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959337,"updateDate":1691007959337}$SATQ$::jsonb, 1691007959337, 1691007959337),
    ($SATQ$5632ffb4$SATQ$, $SATQ$f0e2a006-14c8-4c8a-948b-c193476d843a$SATQ$::uuid, $SATQ$171d3f94-ce35-4de4-82a9-c4b91eb2e087$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>In a study of the cognitive abilities of white-faced capuchin monkeys (<em>Cebus imitator</em>), researchers neglected to control for the physical difficulty of the tasks they used to evaluate the monkeys. The cognitive abilities of monkeys given problems requiring little dexterity, such as sliding a panel to retrieve food, were judged by the same criteria as were those of monkeys given physically demanding problems, such as unscrewing a bottle and inserting a straw. The results of the study, therefore, <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"8265ee70-5ae7-4047-bc96-737065e0c7bc","content":"<p>could suggest that there are differences in cognitive ability among the monkeys even though such differences may not actually exist.</p>"},{"id":"f16c5577-f94d-4fab-af05-fff7c259ec17","content":"<p>are useful for identifying tasks that the monkeys lack the cognitive capacity to perform but not for identifying tasks that the monkeys can perform.&nbsp;</p>"},{"id":"1de2a19a-5ff6-41bd-8a61-9f9ffca96203","content":"<p>should not be taken as indicative of the cognitive abilities of any monkey species other than <em>C. imitator</em>.</p>"},{"id":"1fbcdc2f-19d5-4c5f-b1fb-a3f34cc8dff6","content":"<p>reveal more about the monkeys&rsquo; cognitive abilities when solving artificial problems than when solving problems encountered in the wild.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["8265ee70-5ae7-4047-bc96-737065e0c7bc"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it presents the conclusion that most logically follows from the text&rsquo;s discussion of the study of capuchin monkeys&rsquo; cognitive abilities. The text explains that the study failed to distinguish between outcomes for the tasks performed by the capuchin monkeys, such that simpler tasks requiring less dexterity, or skill, were judged by the same criteria as tasks that demanded more dexterity. Because the study didn&rsquo;t account for this discrepancy, the researchers might have assumed that observed differences in performance were due to the abilities of the monkeys rather than the complexity of the tasks. In other words, the results may suggest cognitive differences among the monkeys even though such differences may not really exist. </p><p>Choice B is incorrect because the text focuses on the fact that the tasks assigned to the capuchin monkeys in the study varied in difficulty and that the variety wasn&rsquo;t taken into consideration. The text doesn&rsquo;t suggest that the capuchin monkeys couldn&rsquo;t perform certain tasks, just that some tasks were more difficult to do. Choice C is incorrect because the text doesn&rsquo;t suggest that the study&rsquo;s results are indicative of the abilities of capuchin monkeys but not of other monkey species; in fact, the text suggests that the results may not even be an accurate reflection of capuchin monkeys&rsquo; abilities.&nbsp;Choice D is incorrect because the text doesn&rsquo;t indicate that the researchers compared results for artificial tasks with those for tasks encountered in the wild, although the tasks described in the text&mdash;sliding a panel and putting a straw in a bottle&mdash;are presumably artificial. </p>$SATQ$, false, 0, $SATQ$OSP-002-INF$SATQ$, $SATQ$$SATQ$, $SATQ$8704a615-4a30-483a-86fc-2d4ffafa6d61$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"5632ffb4","external_id":"f0e2a006-14c8-4c8a-948b-c193476d843a","vaultid":"171d3f94-ce35-4de4-82a9-c4b91eb2e087","uId":"988cb511-3d68-453b-9c85-bfe16c86c04c","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>In a study of the cognitive abilities of white-faced capuchin monkeys (<em>Cebus imitator</em>), researchers neglected to control for the physical difficulty of the tasks they used to evaluate the monkeys. The cognitive abilities of monkeys given problems requiring little dexterity, such as sliding a panel to retrieve food, were judged by the same criteria as were those of monkeys given physically demanding problems, such as unscrewing a bottle and inserting a straw. The results of the study, therefore, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"8265ee70-5ae7-4047-bc96-737065e0c7bc","content":"<p>could suggest that there are differences in cognitive ability among the monkeys even though such differences may not actually exist.</p>"},{"id":"f16c5577-f94d-4fab-af05-fff7c259ec17","content":"<p>are useful for identifying tasks that the monkeys lack the cognitive capacity to perform but not for identifying tasks that the monkeys can perform.&nbsp;</p>"},{"id":"1de2a19a-5ff6-41bd-8a61-9f9ffca96203","content":"<p>should not be taken as indicative of the cognitive abilities of any monkey species other than <em>C. imitator</em>.</p>"},{"id":"1fbcdc2f-19d5-4c5f-b1fb-a3f34cc8dff6","content":"<p>reveal more about the monkeys&rsquo; cognitive abilities when solving artificial problems than when solving problems encountered in the wild.</p>"}],"keys":["8265ee70-5ae7-4047-bc96-737065e0c7bc"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it presents the conclusion that most logically follows from the text&rsquo;s discussion of the study of capuchin monkeys&rsquo; cognitive abilities. The text explains that the study failed to distinguish between outcomes for the tasks performed by the capuchin monkeys, such that simpler tasks requiring less dexterity, or skill, were judged by the same criteria as tasks that demanded more dexterity. Because the study didn&rsquo;t account for this discrepancy, the researchers might have assumed that observed differences in performance were due to the abilities of the monkeys rather than the complexity of the tasks. In other words, the results may suggest cognitive differences among the monkeys even though such differences may not really exist. </p><p>Choice B is incorrect because the text focuses on the fact that the tasks assigned to the capuchin monkeys in the study varied in difficulty and that the variety wasn&rsquo;t taken into consideration. The text doesn&rsquo;t suggest that the capuchin monkeys couldn&rsquo;t perform certain tasks, just that some tasks were more difficult to do. Choice C is incorrect because the text doesn&rsquo;t suggest that the study&rsquo;s results are indicative of the abilities of capuchin monkeys but not of other monkey species; in fact, the text suggests that the results may not even be an accurate reflection of capuchin monkeys&rsquo; abilities.&nbsp;Choice D is incorrect because the text doesn&rsquo;t indicate that the researchers compared results for artificial tasks with those for tasks encountered in the wild, although the tasks described in the text&mdash;sliding a panel and putting a straw in a bottle&mdash;are presumably artificial. </p>","parenttemplatename":"OSP-002-INF","parenttemplateid":"","templateclusterid":"8704a615-4a30-483a-86fc-2d4ffafa6d61","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959311,"updateDate":1691007959311}$SATQ$::jsonb, 1691007959311, 1691007959311),
    ($SATQ$56f477fb$SATQ$, $SATQ$483cec0f-fa36-49b0-b170-d9f66685471a$SATQ$::uuid, $SATQ$90c21773-5206-4161-8d4e-9b179d11157d$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Distribution of Ecosystem Services Affected by Invasive Species by Service Type</p></caption><thead><tr><th scope="col" style="text-align: center; vertical-align: bottom;">Region (Overall)</th><th scope="col" style="text-align: center; vertical-align: bottom;">Provisioning (75%)</th><th scope="col" style="text-align: center; vertical-align: bottom;">Regulating (21%)</th><th scope="col" style="text-align: center; vertical-align: bottom;">Cultural (4%)</th></tr></thead><tbody><tr><th scope="row" style="text-align: left;">West</th><td style="text-align: center;">73%</td><td style="text-align: center;">27%</td><td style="text-align: center;">0%</td></tr><tr><th scope="row" style="text-align: left;">North</th><td style="text-align: center;">88%</td><td style="text-align: center;">12%</td><td style="text-align: center;">0%</td></tr><tr><th scope="row" style="text-align: left;">South</th><td style="text-align: center;">79%</td><td style="text-align: center;">14%</td><td style="text-align: center;">7%</td></tr><tr><th scope="row" style="text-align: left;">East</th><td style="text-align: center;">83%</td><td style="text-align: center;">6%</td><td style="text-align: center;">11%</td></tr><tr><th scope="row" style="text-align: left;">Central</th><td style="text-align: center;">33%</td><td style="text-align: center;">67%</td><td style="text-align: center;">0%</td></tr></tbody></table></figure></p>
<p>To assess the impact of invasive species on ecosystems in Africa, Benis N. Egoh and colleagues reviewed government reports from those nations about how invasive species are undermining ecosystem services (aspects of the ecosystem on which residents depend). The services were sorted into three categories: provisioning (material resources from the ecosystem), regulating (natural processes such as cleaning the air or water), and cultural (nonmaterial benefits of ecosystems). Egoh and her team assert that countries in each region reported effects on provisioning services and that provisioning services represent the majority of the reported services.</p>$SATQ$, $SATQ$<p>Which choice best describes data from the table that support Egoh and colleagues&rsquo; assertion?</p>$SATQ$, $SATQ$[{"id":"85c91c72-f164-4840-a326-b6624cf09046","content":"<p>Provisioning services represent 73% of the services reported for the West region and 33% of those for the Central region, but they represent 75% of the services reported overall.</p>"},{"id":"5c9d1d40-8a31-4cbe-98ce-6ad966e39b92","content":"<p>None of the percentages shown for provisioning services are lower than 33%, and the overall percentage shown for provisioning services is 75%.</p>"},{"id":"45869694-5fb3-45a7-85c9-1a0e96909c4f","content":"<p>Provisioning services are shown for each region, while no cultural services are shown for some regions.</p>"},{"id":"c2f7e6f1-7080-4489-892d-0d1e8ab386d5","content":"<p>The greatest percentage shown for provisioning services is 88% for the North region, and the least shown for provisioning services is 33% for the Central region.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["5c9d1d40-8a31-4cbe-98ce-6ad966e39b92"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The finding that all the regions reported at least some effects on provisioning services supports the first part of the assertion. And the fact that provisioning services comprise 75% of the reported services overall supports the second part of the assertion. </p><p>Choice A is incorrect. This choice doesn&rsquo;t fully support the assertion. It doesn&rsquo;t include the finding that all the regions (not just Central and West) reported at least some effects on provisioning services. Choice C is incorrect. This choice doesn&rsquo;t fully support the assertion. It doesn&rsquo;t demonstrate that provisioning services represent the majority of the reported services overall. Choice D is incorrect. This choice doesn&rsquo;t fully support the assertion. It doesn&rsquo;t demonstrate that provisioning services represent the majority of the reported services overall. </p>$SATQ$, false, 0, $SATQ$OSP-KA-QUA-H004$SATQ$, $SATQ$$SATQ$, $SATQ$4ddcd146-8148-4af3-81ca-9270d47a401a$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"56f477fb","external_id":"483cec0f-fa36-49b0-b170-d9f66685471a","vaultid":"90c21773-5206-4161-8d4e-9b179d11157d","uId":"ec3d9b99-66cc-495e-bb2e-3afe49def0ff","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Distribution of Ecosystem Services Affected by Invasive Species by Service Type</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Region (Overall)</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Provisioning (75%)</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Regulating (21%)</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Cultural (4%)</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: left;\">West</th><td style=\"text-align: center;\">73%</td><td style=\"text-align: center;\">27%</td><td style=\"text-align: center;\">0%</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">North</th><td style=\"text-align: center;\">88%</td><td style=\"text-align: center;\">12%</td><td style=\"text-align: center;\">0%</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">South</th><td style=\"text-align: center;\">79%</td><td style=\"text-align: center;\">14%</td><td style=\"text-align: center;\">7%</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">East</th><td style=\"text-align: center;\">83%</td><td style=\"text-align: center;\">6%</td><td style=\"text-align: center;\">11%</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Central</th><td style=\"text-align: center;\">33%</td><td style=\"text-align: center;\">67%</td><td style=\"text-align: center;\">0%</td></tr></tbody></table></figure></p>\n<p>To assess the impact of invasive species on ecosystems in Africa, Benis N. Egoh and colleagues reviewed government reports from those nations about how invasive species are undermining ecosystem services (aspects of the ecosystem on which residents depend). The services were sorted into three categories: provisioning (material resources from the ecosystem), regulating (natural processes such as cleaning the air or water), and cultural (nonmaterial benefits of ecosystems). Egoh and her team assert that countries in each region reported effects on provisioning services and that provisioning services represent the majority of the reported services.</p>","stem":"<p>Which choice best describes data from the table that support Egoh and colleagues&rsquo; assertion?</p>","answerOptions":[{"id":"85c91c72-f164-4840-a326-b6624cf09046","content":"<p>Provisioning services represent 73% of the services reported for the West region and 33% of those for the Central region, but they represent 75% of the services reported overall.</p>"},{"id":"5c9d1d40-8a31-4cbe-98ce-6ad966e39b92","content":"<p>None of the percentages shown for provisioning services are lower than 33%, and the overall percentage shown for provisioning services is 75%.</p>"},{"id":"45869694-5fb3-45a7-85c9-1a0e96909c4f","content":"<p>Provisioning services are shown for each region, while no cultural services are shown for some regions.</p>"},{"id":"c2f7e6f1-7080-4489-892d-0d1e8ab386d5","content":"<p>The greatest percentage shown for provisioning services is 88% for the North region, and the least shown for provisioning services is 33% for the Central region.</p>"}],"keys":["5c9d1d40-8a31-4cbe-98ce-6ad966e39b92"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The finding that all the regions reported at least some effects on provisioning services supports the first part of the assertion. And the fact that provisioning services comprise 75% of the reported services overall supports the second part of the assertion. </p><p>Choice A is incorrect. This choice doesn&rsquo;t fully support the assertion. It doesn&rsquo;t include the finding that all the regions (not just Central and West) reported at least some effects on provisioning services. Choice C is incorrect. This choice doesn&rsquo;t fully support the assertion. It doesn&rsquo;t demonstrate that provisioning services represent the majority of the reported services overall. Choice D is incorrect. This choice doesn&rsquo;t fully support the assertion. It doesn&rsquo;t demonstrate that provisioning services represent the majority of the reported services overall. </p>","parenttemplatename":"OSP-KA-QUA-H004","parenttemplateid":"","templateclusterid":"4ddcd146-8148-4af3-81ca-9270d47a401a","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959369,"updateDate":1691007959369}$SATQ$::jsonb, 1691007959369, 1691007959369),
    ($SATQ$57303718$SATQ$, $SATQ$a358f59f-7a4a-4af5-a2a8-37a11ebbbec3$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>&ldquo;Looking Back on Girlhood&rdquo; is an 1892 short story by Sarah Orne Jewett. In the story, the narrator explains that she prefers her hometown to other places she has visited: <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which quotation from &ldquo;Looking Back on Girlhood&rdquo; most effectively illustrates this claim?</p>$SATQ$, $SATQ$[{"id":"ca91439d-cfa9-4fbf-810e-2461e8f61f93","content":"<p>&ldquo;There is always something fresh, something to be traced or discovered, something particularly to be remembered.&rdquo;&nbsp;</p>"},{"id":"57a1cedc-25a5-4d86-a8d9-8080a78c91eb","content":"<p>&ldquo;Two large rivers join just below the village at the head of tide-water, and these, with the great inflow from the sea, make a magnificent stream, bordered by lovely green fields that slope gently to long lines of willows at the water&rsquo;s edge.&rdquo;</p>"},{"id":"fb04c19b-2f4e-49d6-a00a-2c0409774b5f","content":"<p>&ldquo;I have had a good deal of journeying in my life, and taken great delight in it, but I have never taken greater delight than in my rides and drives and tramps and voyages within the borders of my native town.&rdquo;</p>"},{"id":"7de709b3-9ee3-49ed-8b57-29ef1f9d31f5","content":"<p>&ldquo;There is never-ending pleasure in making one&rsquo;s self familiar with such a region.&rdquo;</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["fb04c19b-2f4e-49d6-a00a-2c0409774b5f"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most effectively illustrates the claim that the narrator prefers her hometown to other places she has visited. In the quotation, the narrator compares how she feels about places she has traveled to how she feels about the town she&rsquo;s from. The narrator states that although the many journeys she has made in her lifetime have brought her much pleasure, she has gained the most enjoyment from her experiences inside the borders of her hometown.</p><p>Choice A is incorrect because it doesn&rsquo;t express that the narrator likes her hometown better than other places she has visited; instead, the quotation describes something unspecified in positive terms, saying it continues to offer new things to explore and remember. Choice B is incorrect. Although the quotation praises a landscape surrounding a village, it doesn&rsquo;t specify that this village is the narrator&rsquo;s hometown, nor does it express a preference for this village over other places the narrator has visited. Choice D is incorrect. Although the quotation describes enjoyment from getting to know a region, it doesn&rsquo;t compare the narrator&rsquo;s feelings for this region with her feelings for her hometown.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"57303718","external_id":"a358f59f-7a4a-4af5-a2a8-37a11ebbbec3","vaultid":null,"uId":"3959103c-3ee9-4f6a-a1bf-1b53f30a1212","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>&ldquo;Looking Back on Girlhood&rdquo; is an 1892 short story by Sarah Orne Jewett. In the story, the narrator explains that she prefers her hometown to other places she has visited: <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which quotation from &ldquo;Looking Back on Girlhood&rdquo; most effectively illustrates this claim?</p>","answerOptions":[{"id":"ca91439d-cfa9-4fbf-810e-2461e8f61f93","content":"<p>&ldquo;There is always something fresh, something to be traced or discovered, something particularly to be remembered.&rdquo;&nbsp;</p>"},{"id":"57a1cedc-25a5-4d86-a8d9-8080a78c91eb","content":"<p>&ldquo;Two large rivers join just below the village at the head of tide-water, and these, with the great inflow from the sea, make a magnificent stream, bordered by lovely green fields that slope gently to long lines of willows at the water&rsquo;s edge.&rdquo;</p>"},{"id":"fb04c19b-2f4e-49d6-a00a-2c0409774b5f","content":"<p>&ldquo;I have had a good deal of journeying in my life, and taken great delight in it, but I have never taken greater delight than in my rides and drives and tramps and voyages within the borders of my native town.&rdquo;</p>"},{"id":"7de709b3-9ee3-49ed-8b57-29ef1f9d31f5","content":"<p>&ldquo;There is never-ending pleasure in making one&rsquo;s self familiar with such a region.&rdquo;</p>"}],"keys":["fb04c19b-2f4e-49d6-a00a-2c0409774b5f"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most effectively illustrates the claim that the narrator prefers her hometown to other places she has visited. In the quotation, the narrator compares how she feels about places she has traveled to how she feels about the town she&rsquo;s from. The narrator states that although the many journeys she has made in her lifetime have brought her much pleasure, she has gained the most enjoyment from her experiences inside the borders of her hometown.</p><p>Choice A is incorrect because it doesn&rsquo;t express that the narrator likes her hometown better than other places she has visited; instead, the quotation describes something unspecified in positive terms, saying it continues to offer new things to explore and remember. Choice B is incorrect. Although the quotation praises a landscape surrounding a village, it doesn&rsquo;t specify that this village is the narrator&rsquo;s hometown, nor does it express a preference for this village over other places the narrator has visited. Choice D is incorrect. Although the quotation describes enjoyment from getting to know a region, it doesn&rsquo;t compare the narrator&rsquo;s feelings for this region with her feelings for her hometown.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323045,"updateDate":1730147323045}$SATQ$::jsonb, 1730147323045, 1730147323045),
    ($SATQ$57485f5e$SATQ$, $SATQ$d490e4a5-bf54-48b3-a21c-27e521f53d3c$SATQ$::uuid, $SATQ$ba54bede-29bd-4340-866d-4dba8bcc9ecf$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is adapted from Johanna Spyri&rsquo;s 1881 novel <em>Heidi</em> (translated by Elisabeth Stork in 1915). Eight-year-old Heidi and her friend&rsquo;s grandmother are looking at some illustrated books.</p>
<blockquote>
<p>Heidi had come and was looking with wondering eyes at the splendid pictures in the large books, that Grandmama was showing her. Suddenly she screamed aloud, for there on the picture she saw a peaceful flock grazing on a green pasture. In the middle a shepherd was standing, leaning on his crook. The setting sun was shedding a golden light over everything. With glowing eyes Heidi devoured the scene.</p>
</blockquote>$SATQ$, $SATQ$<p>Which choice best states the main idea of the text?</p>$SATQ$, $SATQ$[{"id":"64ec4f68-a2cd-4171-b21c-1b22213af7f1","content":"<p>Heidi is upset until she sees a serene image of a pasture in one of Grandmama&rsquo;s books.</p>"},{"id":"6e58bce6-c2ca-4a15-82db-9a00dee88aec","content":"<p>Heidi is delighted and fascinated by an image she sees in one of Grandmama&rsquo;s books.</p>"},{"id":"b8344d87-0d83-4d19-a6dd-079e28926c9f","content":"<p>Heidi is initially frightened by an image in one of Grandmama&rsquo;s books but quickly comes to appreciate its beauty.</p>"},{"id":"b96cbe9b-4215-4419-880d-91a8887a457a","content":"<p>Heidi is inspecting an image in one of Grandmama&rsquo;s books because she has never seen a shepherd with his sheep before.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["6e58bce6-c2ca-4a15-82db-9a00dee88aec"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most effectively states the main idea of the text, which is that Heidi is delighted and fascinated by an image she sees in one of Grandmama&rsquo;s books. In the text, Heidi screams upon first seeing the picture of the green pasture. In another context, such a reaction might suggest fear, but here the reaction is followed by descriptions of an image that&rsquo;s peaceful rather than scary. The text goes on to describe Heidi&rsquo;s eyes as &ldquo;glowing&rdquo; and states that she &ldquo;devoured the scene,&rdquo; suggesting that the image delights and fascinates her so much that she wants to examine every detail. Together, these descriptions suggest that Heidi is thrilled and intrigued by the image in the book. </p><p>Choice A is incorrect because there&rsquo;s nothing in the text to suggest that Heidi is upset before seeing the peaceful image of the green pasture. Before Heidi sees that image, the text describes her as &ldquo;looking with wondering eyes at the splendid pictures&rdquo; in the book, suggesting that Heidi is intrigued, not that she&rsquo;s unhappy. Choice C is incorrect. Although Heidi screams upon first seeing the image, the text&rsquo;s description of the image and Heidi&rsquo;s other reactions to it suggest that she is screaming with delight, not fear. The text describes the images in the book as &ldquo;splendid&rdquo; and the particular image that causes her to scream as peaceful rather than frightening. It also describes Heidi&rsquo;s eyes as &ldquo;glowing&rdquo; and states that she &ldquo;devoured the scene,&rdquo; suggesting that the image of the green pasture delights and fascinates her so much that she wants to examine every detail. Choice D is incorrect because it&rsquo;s unclear from the text whether Heidi has ever seen a shepherd with his sheep before. The text merely suggests that she is delighted and fascinated by the image of the shepherd and his sheep. </p>$SATQ$, false, 0, $SATQ$OSP-028-CID$SATQ$, $SATQ$$SATQ$, $SATQ$1877746d-a88f-4e5a-86c1-87778be53173$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"57485f5e","external_id":"d490e4a5-bf54-48b3-a21c-27e521f53d3c","vaultid":"ba54bede-29bd-4340-866d-4dba8bcc9ecf","uId":"11700439-7ddb-4d59-8e74-de31ed5bb433","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>The following text is adapted from Johanna Spyri&rsquo;s 1881 novel <em>Heidi</em> (translated by Elisabeth Stork in 1915). Eight-year-old Heidi and her friend&rsquo;s grandmother are looking at some illustrated books.</p>\n<blockquote>\n<p>Heidi had come and was looking with wondering eyes at the splendid pictures in the large books, that Grandmama was showing her. Suddenly she screamed aloud, for there on the picture she saw a peaceful flock grazing on a green pasture. In the middle a shepherd was standing, leaning on his crook. The setting sun was shedding a golden light over everything. With glowing eyes Heidi devoured the scene.</p>\n</blockquote>","stem":"<p>Which choice best states the main idea of the text?</p>","answerOptions":[{"id":"64ec4f68-a2cd-4171-b21c-1b22213af7f1","content":"<p>Heidi is upset until she sees a serene image of a pasture in one of Grandmama&rsquo;s books.</p>"},{"id":"6e58bce6-c2ca-4a15-82db-9a00dee88aec","content":"<p>Heidi is delighted and fascinated by an image she sees in one of Grandmama&rsquo;s books.</p>"},{"id":"b8344d87-0d83-4d19-a6dd-079e28926c9f","content":"<p>Heidi is initially frightened by an image in one of Grandmama&rsquo;s books but quickly comes to appreciate its beauty.</p>"},{"id":"b96cbe9b-4215-4419-880d-91a8887a457a","content":"<p>Heidi is inspecting an image in one of Grandmama&rsquo;s books because she has never seen a shepherd with his sheep before.</p>"}],"keys":["6e58bce6-c2ca-4a15-82db-9a00dee88aec"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most effectively states the main idea of the text, which is that Heidi is delighted and fascinated by an image she sees in one of Grandmama&rsquo;s books. In the text, Heidi screams upon first seeing the picture of the green pasture. In another context, such a reaction might suggest fear, but here the reaction is followed by descriptions of an image that&rsquo;s peaceful rather than scary. The text goes on to describe Heidi&rsquo;s eyes as &ldquo;glowing&rdquo; and states that she &ldquo;devoured the scene,&rdquo; suggesting that the image delights and fascinates her so much that she wants to examine every detail. Together, these descriptions suggest that Heidi is thrilled and intrigued by the image in the book. </p><p>Choice A is incorrect because there&rsquo;s nothing in the text to suggest that Heidi is upset before seeing the peaceful image of the green pasture. Before Heidi sees that image, the text describes her as &ldquo;looking with wondering eyes at the splendid pictures&rdquo; in the book, suggesting that Heidi is intrigued, not that she&rsquo;s unhappy. Choice C is incorrect. Although Heidi screams upon first seeing the image, the text&rsquo;s description of the image and Heidi&rsquo;s other reactions to it suggest that she is screaming with delight, not fear. The text describes the images in the book as &ldquo;splendid&rdquo; and the particular image that causes her to scream as peaceful rather than frightening. It also describes Heidi&rsquo;s eyes as &ldquo;glowing&rdquo; and states that she &ldquo;devoured the scene,&rdquo; suggesting that the image of the green pasture delights and fascinates her so much that she wants to examine every detail. Choice D is incorrect because it&rsquo;s unclear from the text whether Heidi has ever seen a shepherd with his sheep before. The text merely suggests that she is delighted and fascinated by the image of the shepherd and his sheep. </p>","parenttemplatename":"OSP-028-CID","parenttemplateid":"","templateclusterid":"1877746d-a88f-4e5a-86c1-87778be53173","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959318,"updateDate":1691007959318}$SATQ$::jsonb, 1691007959318, 1691007959318),
    ($SATQ$575e67df$SATQ$, $SATQ$5818e783-6bbc-430f-8003-9f3967e542b2$SATQ$::uuid, $SATQ$fbf015e1-b047-4cce-ba91-f0005fc0f4b2$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>By running computer simulations of the development of our solar system, Andr&eacute; Izidoro, Rajdeep Dasgupta, and colleagues concluded that the Sun may have been surrounded by three giant dust rings before the planets started to form. The researchers suggest that the materials in the innermost ring became the four planets closest to the Sun, the materials in the middle ring produced the rest of the planets, and the materials in the outermost ring created the asteroids and other small bodies in the region beyond Neptune. In one simulation, the researchers delayed the initial formation of the middle ring, causing oversized super-Earths to begin developing from the innermost ring. The researchers therefore hypothesize that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"03bc501b-4768-4366-92a1-01a96b1cfc01","content":"<p>the middle ring formed earlier in the solar system&rsquo;s development than the initial simulations suggested.&nbsp;</p>"},{"id":"2790165b-78e1-47f5-ba46-9c41eff362e8","content":"<p>the timing of the initial formation of the middle ring played an important role in determining the eventual size of Earth.</p>"},{"id":"e8abefe9-5d57-40c8-916f-1c48b5781e27","content":"<p>if the formation of the outermost ring had occurred earlier in a simulation, all the planets would have become super-Earths.</p>"},{"id":"a5e5addf-8caf-4ffd-b958-581f5302e577","content":"<p>the innermost ring actually formed into all the planets in our solar system, not just the four closest to the Sun.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["2790165b-78e1-47f5-ba46-9c41eff362e8"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most logically follows from the text&rsquo;s discussion of Andr&eacute; Izidoro, Rajdeep Dasgupta, and colleagues&rsquo; computer simulations of our solar system&rsquo;s development. The text begins by stating that the simulations led the researchers to conclude that the solar system likely formed from three giant dust rings that encircled the Sun. The text explains that the four inner planets, including Earth, formed from the innermost ring and that the remaining planets formed from the middle ring. It then explains that in one simulation, the researchers delayed the formation of the middle ring&mdash;that is, they tested to see what would happen if the middle ring had formed later than it actually did. They found that doing so affected the size of the innermost planets, resulting in oversized super-Earths, planets that are much larger than Earth. Since the delayed timing had the effect of changing the size of Earth in the simulation relative to Earth&rsquo;s real size, it&rsquo;s reasonable to conclude that the timing of the middle ring&rsquo;s formation was important in determining Earth&rsquo;s eventual size.&nbsp;</p><p>Choice A is incorrect. Although the text explains that when the researchers delayed the formation of the middle ring in one simulation, the size of the innermost planets was affected (which suggests that the middle ring likely formed earlier than it did in this simulation), the text doesn&rsquo;t indicate that this was an initial simulation&mdash;that is, a simulation that was conducted before other simulations. Moreover, the text makes no reference to the specific results of any other simulations; therefore, there is no basis for comparing any conclusions based on the simulation in which the middle ring&rsquo;s formation was delayed with conclusions based on other simulations. Choice C is incorrect because the text discusses how altering the timing of the formation of the middle ring, not the outermost ring, affected the four innermost planets&rsquo; eventual size in the researchers&rsquo; simulation; therefore, the simulation offers no basis for a conclusion about how the outermost ring&rsquo;s formation affected the size of the planets. Choice D is incorrect because there is nothing in the text to suggest that the innermost ring produced all the solar system&rsquo;s planets. Rather, the text states that the simulations showed that the innermost planets formed from the innermost ring and that the remaining planets formed from the middle ring. &nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-046-INF$SATQ$, $SATQ$$SATQ$, $SATQ$d1a4a0ab-5ad5-402d-8a62-64f16cce64c1$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"575e67df","external_id":"5818e783-6bbc-430f-8003-9f3967e542b2","vaultid":"fbf015e1-b047-4cce-ba91-f0005fc0f4b2","uId":"9fee1bb7-22ca-4019-bb6a-56f7deef2031","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>By running computer simulations of the development of our solar system, Andr&eacute; Izidoro, Rajdeep Dasgupta, and colleagues concluded that the Sun may have been surrounded by three giant dust rings before the planets started to form. The researchers suggest that the materials in the innermost ring became the four planets closest to the Sun, the materials in the middle ring produced the rest of the planets, and the materials in the outermost ring created the asteroids and other small bodies in the region beyond Neptune. In one simulation, the researchers delayed the initial formation of the middle ring, causing oversized super-Earths to begin developing from the innermost ring. The researchers therefore hypothesize that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"03bc501b-4768-4366-92a1-01a96b1cfc01","content":"<p>the middle ring formed earlier in the solar system&rsquo;s development than the initial simulations suggested.&nbsp;</p>"},{"id":"2790165b-78e1-47f5-ba46-9c41eff362e8","content":"<p>the timing of the initial formation of the middle ring played an important role in determining the eventual size of Earth.</p>"},{"id":"e8abefe9-5d57-40c8-916f-1c48b5781e27","content":"<p>if the formation of the outermost ring had occurred earlier in a simulation, all the planets would have become super-Earths.</p>"},{"id":"a5e5addf-8caf-4ffd-b958-581f5302e577","content":"<p>the innermost ring actually formed into all the planets in our solar system, not just the four closest to the Sun.</p>"}],"keys":["2790165b-78e1-47f5-ba46-9c41eff362e8"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most logically follows from the text&rsquo;s discussion of Andr&eacute; Izidoro, Rajdeep Dasgupta, and colleagues&rsquo; computer simulations of our solar system&rsquo;s development. The text begins by stating that the simulations led the researchers to conclude that the solar system likely formed from three giant dust rings that encircled the Sun. The text explains that the four inner planets, including Earth, formed from the innermost ring and that the remaining planets formed from the middle ring. It then explains that in one simulation, the researchers delayed the formation of the middle ring&mdash;that is, they tested to see what would happen if the middle ring had formed later than it actually did. They found that doing so affected the size of the innermost planets, resulting in oversized super-Earths, planets that are much larger than Earth. Since the delayed timing had the effect of changing the size of Earth in the simulation relative to Earth&rsquo;s real size, it&rsquo;s reasonable to conclude that the timing of the middle ring&rsquo;s formation was important in determining Earth&rsquo;s eventual size.&nbsp;</p><p>Choice A is incorrect. Although the text explains that when the researchers delayed the formation of the middle ring in one simulation, the size of the innermost planets was affected (which suggests that the middle ring likely formed earlier than it did in this simulation), the text doesn&rsquo;t indicate that this was an initial simulation&mdash;that is, a simulation that was conducted before other simulations. Moreover, the text makes no reference to the specific results of any other simulations; therefore, there is no basis for comparing any conclusions based on the simulation in which the middle ring&rsquo;s formation was delayed with conclusions based on other simulations. Choice C is incorrect because the text discusses how altering the timing of the formation of the middle ring, not the outermost ring, affected the four innermost planets&rsquo; eventual size in the researchers&rsquo; simulation; therefore, the simulation offers no basis for a conclusion about how the outermost ring&rsquo;s formation affected the size of the planets. Choice D is incorrect because there is nothing in the text to suggest that the innermost ring produced all the solar system&rsquo;s planets. Rather, the text states that the simulations showed that the innermost planets formed from the innermost ring and that the remaining planets formed from the middle ring. &nbsp;</p>","parenttemplatename":"OSP-046-INF","parenttemplateid":"","templateclusterid":"d1a4a0ab-5ad5-402d-8a62-64f16cce64c1","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959323,"updateDate":1691007959323}$SATQ$::jsonb, 1691007959323, 1691007959323),
    ($SATQ$58e9e497$SATQ$, $SATQ$6cab30c3-74f3-4b95-8bbc-00892bfbb3c0$SATQ$::uuid, $SATQ$f167088e-edd4-46c1-9264-3a50815a0dbf$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>In the early nineteenth century, some Euro-American farmers in the northeastern United States used agricultural techniques developed by the Haudenosaunee (Iroquois) people centuries earlier, but it seems that few of those farmers had actually seen Haudenosaunee farms firsthand. Barring the possibility of several farmers of the same era independently developing techniques that the Haudenosaunee people had already invented, these facts most strongly suggest that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"6b289862-6937-41f2-9562-d063065a598a","content":"<p>those farmers learned the techniques from other people who were more directly influenced by Haudenosaunee practices.</p>"},{"id":"d9faddfe-0373-4297-8c76-a51242a3a376","content":"<p>the crops typically cultivated by Euro-American farmers in the northeastern United States were not well suited to Haudenosaunee farming techniques.</p>"},{"id":"a880375f-78aa-4332-b5ce-efac02136686","content":"<p>Haudenosaunee farming techniques were widely used in regions outside the northeastern United States.</p>"},{"id":"3f2cee79-d43e-4796-8a12-ee7da331d27b","content":"<p>Euro-American farmers only began to recognize the benefits of Haudenosaunee farming techniques late in the nineteenth century.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["6b289862-6937-41f2-9562-d063065a598a"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of Euro-American farmers&rsquo; use of Haudenosaunee agricultural techniques. According to the text, some Euro-American farmers were using these techniques in the early nineteenth century despite few of the farmers having seen Haudenosaunee farms. One explanation for these facts might be that the farmers developed techniques on their own that already had been invented centuries earlier by the Haudenosaunee people, but the text explicitly bars, or rules out, this explanation. If Euro-American farmers didn&rsquo;t learn these techniques from direct observation of Haudenosaunee practices and didn&rsquo;t invent the techniques independently, then the most logical explanation is that they learned the techniques from other people who were more directly influenced by Haudenosaunee practices than the farmers themselves were. Once they learned about Haudenosaunee agricultural practices, Euro-American farmers could then apply those practices to their own farming. </p><p>Choice B is incorrect because the fact that some Euro-American farmers in the northeastern United States were using Haudenosaunee techniques suggests that the techniques were likely useful for the crops the farmers raised, not that the crops typically cultivated by the farmers were not well suited to Haudenosaunee farming techniques. If the farmers&rsquo; crops were ill suited to the techniques, it&rsquo;s unlikely that the farmers would have used those techniques. Choice C is incorrect because the text indicates only that Haudenosaunee agricultural techniques were used by Euro-American farmers in the northeastern United States, not that these techniques were widely used outside this region.&nbsp;Choice D is incorrect because the text states that some Euro-American farmers were using Haudenosaunee farming techniques early in the nineteenth century. This suggests that some Euro-American farmers were beginning to recognize the benefits of these techniques near the start of the century, not that such farmers only began to recognize the benefits of the techniques much later. </p>$SATQ$, false, 0, $SATQ$OSP-003-INF$SATQ$, $SATQ$$SATQ$, $SATQ$4934fdaa-81d3-4ae6-a4f9-7c80e7149543$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"58e9e497","external_id":"6cab30c3-74f3-4b95-8bbc-00892bfbb3c0","vaultid":"f167088e-edd4-46c1-9264-3a50815a0dbf","uId":"171b1194-e381-40c0-83c6-bb31f4850a20","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>In the early nineteenth century, some Euro-American farmers in the northeastern United States used agricultural techniques developed by the Haudenosaunee (Iroquois) people centuries earlier, but it seems that few of those farmers had actually seen Haudenosaunee farms firsthand. Barring the possibility of several farmers of the same era independently developing techniques that the Haudenosaunee people had already invented, these facts most strongly suggest that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"6b289862-6937-41f2-9562-d063065a598a","content":"<p>those farmers learned the techniques from other people who were more directly influenced by Haudenosaunee practices.</p>"},{"id":"d9faddfe-0373-4297-8c76-a51242a3a376","content":"<p>the crops typically cultivated by Euro-American farmers in the northeastern United States were not well suited to Haudenosaunee farming techniques.</p>"},{"id":"a880375f-78aa-4332-b5ce-efac02136686","content":"<p>Haudenosaunee farming techniques were widely used in regions outside the northeastern United States.</p>"},{"id":"3f2cee79-d43e-4796-8a12-ee7da331d27b","content":"<p>Euro-American farmers only began to recognize the benefits of Haudenosaunee farming techniques late in the nineteenth century.</p>"}],"keys":["6b289862-6937-41f2-9562-d063065a598a"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of Euro-American farmers&rsquo; use of Haudenosaunee agricultural techniques. According to the text, some Euro-American farmers were using these techniques in the early nineteenth century despite few of the farmers having seen Haudenosaunee farms. One explanation for these facts might be that the farmers developed techniques on their own that already had been invented centuries earlier by the Haudenosaunee people, but the text explicitly bars, or rules out, this explanation. If Euro-American farmers didn&rsquo;t learn these techniques from direct observation of Haudenosaunee practices and didn&rsquo;t invent the techniques independently, then the most logical explanation is that they learned the techniques from other people who were more directly influenced by Haudenosaunee practices than the farmers themselves were. Once they learned about Haudenosaunee agricultural practices, Euro-American farmers could then apply those practices to their own farming. </p><p>Choice B is incorrect because the fact that some Euro-American farmers in the northeastern United States were using Haudenosaunee techniques suggests that the techniques were likely useful for the crops the farmers raised, not that the crops typically cultivated by the farmers were not well suited to Haudenosaunee farming techniques. If the farmers&rsquo; crops were ill suited to the techniques, it&rsquo;s unlikely that the farmers would have used those techniques. Choice C is incorrect because the text indicates only that Haudenosaunee agricultural techniques were used by Euro-American farmers in the northeastern United States, not that these techniques were widely used outside this region.&nbsp;Choice D is incorrect because the text states that some Euro-American farmers were using Haudenosaunee farming techniques early in the nineteenth century. This suggests that some Euro-American farmers were beginning to recognize the benefits of these techniques near the start of the century, not that such farmers only began to recognize the benefits of the techniques much later. </p>","parenttemplatename":"OSP-003-INF","parenttemplateid":"","templateclusterid":"4934fdaa-81d3-4ae6-a4f9-7c80e7149543","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959312,"updateDate":1691007959312}$SATQ$::jsonb, 1691007959312, 1691007959312),
    ($SATQ$5b4829d2$SATQ$, $SATQ$0b8f215d-1b22-42fb-8f6b-1fb5afd5de8d$SATQ$::uuid, $SATQ$4a041e5b-4ece-4d26-985b-5562f363f149$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>Researchers wanted to study how consumers&rsquo; reactions to an ad may be affected by other ads. The researchers began by showing study participants an ad for a product, with some seeing a less detailed ad and others seeing a more detailed one. Then, all participants viewed the same second ad for a store and shared their opinion of the store based on this second ad. Participants who had first seen an ad less detailed than the second ad had a higher opinion of the store than the participants who had first seen a more detailed ad. The researchers concluded that reactions to an ad may be affected by <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"d9e96a5c-f47d-4ae0-81a0-efbd367d8e45","content":"<p>the number of people who viewed the ad.</p>"},{"id":"cc1046dc-9b09-4f0c-99e9-4c8f6e983522","content":"<p>the length of time viewing previous ads.&nbsp;</p>"},{"id":"9324eaf6-8235-4118-a88a-57fa9d7017d4","content":"<p>the amount of detail viewed in previous ads.</p>"},{"id":"ddab6f99-21d7-4d1b-94df-d5a13fd9ef2c","content":"<p>the time of day that the ad is viewed.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["9324eaf6-8235-4118-a88a-57fa9d7017d4"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The passage tells us that participants who had seen a less detailed ad for a product beforehand had a higher opinion of the store than those who had seen a more detailed ad. This suggests that reactions to an ad may be affected by the amount of detail viewed in previous ads. </p><p>Choice A is incorrect. The passage doesn&rsquo;t mention the number of people who viewed the ad, so there&rsquo;s no basis for this inference. Choice B is incorrect. The passage doesn&rsquo;t mention the length of time viewing previous ads, so there&rsquo;s no basis for this inference. Choice D is incorrect. The passage doesn&rsquo;t mention the time of day that the ad is viewed, so there&rsquo;s no basis for this inference. </p>$SATQ$, false, 0, $SATQ$OSP-KA-INF-E008$SATQ$, $SATQ$$SATQ$, $SATQ$4fe9d9bd-e67a-4e3e-a638-cb3ce7c37fcc$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"5b4829d2","external_id":"0b8f215d-1b22-42fb-8f6b-1fb5afd5de8d","vaultid":"4a041e5b-4ece-4d26-985b-5562f363f149","uId":"dcecdaae-af0a-4dda-9915-0627ee46616d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>Researchers wanted to study how consumers&rsquo; reactions to an ad may be affected by other ads. The researchers began by showing study participants an ad for a product, with some seeing a less detailed ad and others seeing a more detailed one. Then, all participants viewed the same second ad for a store and shared their opinion of the store based on this second ad. Participants who had first seen an ad less detailed than the second ad had a higher opinion of the store than the participants who had first seen a more detailed ad. The researchers concluded that reactions to an ad may be affected by <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"d9e96a5c-f47d-4ae0-81a0-efbd367d8e45","content":"<p>the number of people who viewed the ad.</p>"},{"id":"cc1046dc-9b09-4f0c-99e9-4c8f6e983522","content":"<p>the length of time viewing previous ads.&nbsp;</p>"},{"id":"9324eaf6-8235-4118-a88a-57fa9d7017d4","content":"<p>the amount of detail viewed in previous ads.</p>"},{"id":"ddab6f99-21d7-4d1b-94df-d5a13fd9ef2c","content":"<p>the time of day that the ad is viewed.</p>"}],"keys":["9324eaf6-8235-4118-a88a-57fa9d7017d4"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The passage tells us that participants who had seen a less detailed ad for a product beforehand had a higher opinion of the store than those who had seen a more detailed ad. This suggests that reactions to an ad may be affected by the amount of detail viewed in previous ads. </p><p>Choice A is incorrect. The passage doesn&rsquo;t mention the number of people who viewed the ad, so there&rsquo;s no basis for this inference. Choice B is incorrect. The passage doesn&rsquo;t mention the length of time viewing previous ads, so there&rsquo;s no basis for this inference. Choice D is incorrect. The passage doesn&rsquo;t mention the time of day that the ad is viewed, so there&rsquo;s no basis for this inference. </p>","parenttemplatename":"OSP-KA-INF-E008","parenttemplateid":"","templateclusterid":"4fe9d9bd-e67a-4e3e-a638-cb3ce7c37fcc","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959368,"updateDate":1691007959368}$SATQ$::jsonb, 1691007959368, 1691007959368),
    ($SATQ$5b74feb9$SATQ$, $SATQ$68948483-1f64-4760-a657-ec2406b34c19$SATQ$::uuid, $SATQ$11122aa7-4e6d-44e8-bb66-db68df180cd2$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Political scientists who favor the traditional view of voter behavior claim that voting in an election does not change a voter&rsquo;s attitude toward the candidates in that election. Focusing on each US presidential election from 1976 to 1996, Ebonya Washington and Sendhil Mullainathan tested this claim by distinguishing between subjects who had just become old enough to vote (around half of whom actually voted) and otherwise similar subjects who were slightly too young to vote (and thus none of whom voted). Washington and Mullainathan compared the attitudes of the groups of subjects toward the winning candidate two years after each election.</p>$SATQ$, $SATQ$<p>Which finding from Washington and Mullainathan&rsquo;s study, if true, would most directly weaken the claim made by people who favor the traditional view of voter behavior?</p>$SATQ$, $SATQ$[{"id":"a248eb5e-1952-4721-9932-4a25eed57bb4","content":"<p>Subjects&rsquo; attitudes toward the winning candidate two years after a given election were strongly predicted by subjects&rsquo; general political orientation, regardless of whether subjects were old enough to vote at the time of the election.</p>"},{"id":"39946272-07fb-4bd1-84fa-f9c8f6fcc005","content":"<p>Subjects who were not old enough to vote in a given election held significantly more positive attitudes towards the winning candidate two years later than they held at the time of the election.</p>"},{"id":"bb52f303-111d-41ef-b2f8-52a99c9be9ff","content":"<p>Subjects who voted in a given election held significantly more polarized attitudes toward the winning candidate two years later than did subjects who were not old enough to vote in that election.</p>"},{"id":"0607f2ef-9470-4d63-878d-623156e3626e","content":"<p>Two years after a given election, subjects who voted and subjects who were not old enough to vote were significantly more likely to express negative attitudes than positive attitudes toward the winning candidate in that election.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["bb52f303-111d-41ef-b2f8-52a99c9be9ff"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it presents a finding that, if true, would weaken the claim made by people who favor the traditional view of voter behavior. According to the text, people who favor that view believe that voting in an election doesn&rsquo;t change a voter&rsquo;s attitude toward the candidates in that election. If Washington and Mullainathan found that two years after an election, attitudes toward the winning candidate were significantly more polarized among subjects who had voted than among subjects who had been too young to vote, that would suggest that the act of voting did have an effect on the voters&rsquo; attitudes toward the candidates, which would undermine the claim that voting doesn&rsquo;t change voters&rsquo; attitudes. </p><p>Choice A is incorrect because a finding about links between subjects&rsquo; attitudes and general political orientation, regardless of age and ability to vote, wouldn&rsquo;t address the presence or absence of changes in attitudes among those subjects who did actually vote. Therefore, the finding wouldn&rsquo;t have any bearing on the claim that voting in an election doesn&rsquo;t change a voter&rsquo;s attitude toward the candidates in that election. Choice B is incorrect because a finding that positive attitudes toward a winning candidate significantly increased in the two years after the election among subjects who had been too young to vote would involve only people who didn&rsquo;t vote; therefore, the finding wouldn&rsquo;t have any bearing on the claim that when people do vote, the act of voting doesn&rsquo;t change their attitudes toward the candidates. Choice D is incorrect because the finding that subjects in both groups were more likely to have negative attitudes than positive attitudes toward the winning candidate two years after an election would reflect all subjects&rsquo; attitudes at one particular time whether they voted or not, rather than the presence or absence of a change in voters&rsquo; attitudes after voting. Therefore, the finding would neither weaken nor strengthen the claim that voting in an election doesn&rsquo;t change a voter&rsquo;s attitude toward the candidates. </p>$SATQ$, false, 0, $SATQ$OSP-307-TXT$SATQ$, $SATQ$$SATQ$, $SATQ$032f9af1-dc63-42f7-8e4b-5d5432ebf947$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"5b74feb9","external_id":"68948483-1f64-4760-a657-ec2406b34c19","vaultid":"11122aa7-4e6d-44e8-bb66-db68df180cd2","uId":"73351493-931e-414f-b351-1e376d0468e0","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Political scientists who favor the traditional view of voter behavior claim that voting in an election does not change a voter&rsquo;s attitude toward the candidates in that election. Focusing on each US presidential election from 1976 to 1996, Ebonya Washington and Sendhil Mullainathan tested this claim by distinguishing between subjects who had just become old enough to vote (around half of whom actually voted) and otherwise similar subjects who were slightly too young to vote (and thus none of whom voted). Washington and Mullainathan compared the attitudes of the groups of subjects toward the winning candidate two years after each election.</p>","stem":"<p>Which finding from Washington and Mullainathan&rsquo;s study, if true, would most directly weaken the claim made by people who favor the traditional view of voter behavior?</p>","answerOptions":[{"id":"a248eb5e-1952-4721-9932-4a25eed57bb4","content":"<p>Subjects&rsquo; attitudes toward the winning candidate two years after a given election were strongly predicted by subjects&rsquo; general political orientation, regardless of whether subjects were old enough to vote at the time of the election.</p>"},{"id":"39946272-07fb-4bd1-84fa-f9c8f6fcc005","content":"<p>Subjects who were not old enough to vote in a given election held significantly more positive attitudes towards the winning candidate two years later than they held at the time of the election.</p>"},{"id":"bb52f303-111d-41ef-b2f8-52a99c9be9ff","content":"<p>Subjects who voted in a given election held significantly more polarized attitudes toward the winning candidate two years later than did subjects who were not old enough to vote in that election.</p>"},{"id":"0607f2ef-9470-4d63-878d-623156e3626e","content":"<p>Two years after a given election, subjects who voted and subjects who were not old enough to vote were significantly more likely to express negative attitudes than positive attitudes toward the winning candidate in that election.</p>"}],"keys":["bb52f303-111d-41ef-b2f8-52a99c9be9ff"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it presents a finding that, if true, would weaken the claim made by people who favor the traditional view of voter behavior. According to the text, people who favor that view believe that voting in an election doesn&rsquo;t change a voter&rsquo;s attitude toward the candidates in that election. If Washington and Mullainathan found that two years after an election, attitudes toward the winning candidate were significantly more polarized among subjects who had voted than among subjects who had been too young to vote, that would suggest that the act of voting did have an effect on the voters&rsquo; attitudes toward the candidates, which would undermine the claim that voting doesn&rsquo;t change voters&rsquo; attitudes. </p><p>Choice A is incorrect because a finding about links between subjects&rsquo; attitudes and general political orientation, regardless of age and ability to vote, wouldn&rsquo;t address the presence or absence of changes in attitudes among those subjects who did actually vote. Therefore, the finding wouldn&rsquo;t have any bearing on the claim that voting in an election doesn&rsquo;t change a voter&rsquo;s attitude toward the candidates in that election. Choice B is incorrect because a finding that positive attitudes toward a winning candidate significantly increased in the two years after the election among subjects who had been too young to vote would involve only people who didn&rsquo;t vote; therefore, the finding wouldn&rsquo;t have any bearing on the claim that when people do vote, the act of voting doesn&rsquo;t change their attitudes toward the candidates. Choice D is incorrect because the finding that subjects in both groups were more likely to have negative attitudes than positive attitudes toward the winning candidate two years after an election would reflect all subjects&rsquo; attitudes at one particular time whether they voted or not, rather than the presence or absence of a change in voters&rsquo; attitudes after voting. Therefore, the finding would neither weaken nor strengthen the claim that voting in an election doesn&rsquo;t change a voter&rsquo;s attitude toward the candidates. </p>","parenttemplatename":"OSP-307-TXT","parenttemplateid":"","templateclusterid":"032f9af1-dc63-42f7-8e4b-5d5432ebf947","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959335,"updateDate":1691007959335}$SATQ$::jsonb, 1691007959335, 1691007959335),
    ($SATQ$5c73f0cc$SATQ$, $SATQ$e9f142be-2f7c-44eb-a99a-aa5eb0e586ac$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<figure class="image"><svg xmlns="http://www.w3.org/2000/svg" width="380" height="424.84" viewBox="0 0 380 424.84" role="img" aria-label="Long description for bar graph titled Test Results for Two New Battery Recycling Processes. The horizontal axis is labeled Lithium-ion battery type. 2 data categories are shown. The vertical axis is labeled Lithium recovered, in percent. It ranges from 0 to 80 in increments of 10. Refer to long description."><g id="ed420550-79eb-48d4-af01-cd27cdd08afd" data-name="Layer 1"><defs>
