m="translate(67.91999816894531 153)" fill="#000000" font-size="19.84" font-family="Crimson Text">50</text><line xmlns="http://www.w3.org/2000/svg" x1="79.91999816894531" y1="172" x2="365" y2="172" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><line xmlns="http://www.w3.org/2000/svg" x1="73.91999816894531" y1="172" x2="85.91999816894531" y2="172" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><text text-anchor="end" transform="translate(67.91999816894531 178)" fill="#000000" font-size="19.84" font-family="Crimson Text">40</text><line xmlns="http://www.w3.org/2000/svg" x1="79.91999816894531" y1="197" x2="365" y2="197" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><line xmlns="http://www.w3.org/2000/svg" x1="73.91999816894531" y1="197" x2="85.91999816894531" y2="197" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><text text-anchor="end" transform="translate(67.91999816894531 203)" fill="#000000" font-size="19.84" font-family="Crimson Text">30</text><line xmlns="http://www.w3.org/2000/svg" x1="79.91999816894531" y1="222" x2="365" y2="222" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><line xmlns="http://www.w3.org/2000/svg" x1="73.91999816894531" y1="222" x2="85.91999816894531" y2="222" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><text text-anchor="end" transform="translate(67.91999816894531 228)" fill="#000000" font-size="19.84" font-family="Crimson Text">20</text><line xmlns="http://www.w3.org/2000/svg" x1="79.91999816894531" y1="247" x2="365" y2="247" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><line xmlns="http://www.w3.org/2000/svg" x1="73.91999816894531" y1="247" x2="85.91999816894531" y2="247" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><text text-anchor="end" transform="translate(67.91999816894531 253)" fill="#000000" font-size="19.84" font-family="Crimson Text">10</text><line xmlns="http://www.w3.org/2000/svg" x1="79.91999816894531" y1="272" x2="365" y2="272" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><line xmlns="http://www.w3.org/2000/svg" x1="73.91999816894531" y1="272" x2="85.91999816894531" y2="272" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><text text-anchor="end" transform="translate(67.91999816894531 278)" fill="#000000" font-size="19.84" font-family="Crimson Text">0</text><text text-anchor="middle" transform="translate(24 172) rotate(-90)" fill="#000000" font-size="19.84" font-family="Crimson Text">Lithium recovered (%)</text><line xmlns="http://www.w3.org/2000/svg" x1="79.91999816894531" y1="72" x2="79.91999816894531" y2="272" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><rect xmlns="http://www.w3.org/2000/svg" x="120.64571271623885" y="197.5" height="74.5" width="40.72571454729353" fill="#B3B3B3" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9"/><rect xmlns="http://www.w3.org/2000/svg" x="161.37142726353238" y="133" height="139" width="40.72571454729353" fill="#333333" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9"/><text xmlns="http://www.w3.org/2000/svg" x="0" y="0" text-anchor="middle" transform="translate(161.37142726353238 291.84)" fill="#000000" font-size="19.84" font-family="Crimson Text">Type A</text><rect xmlns="http://www.w3.org/2000/svg" x="242.82285635811945" y="184.75" height="87.25" width="40.72571454729353" fill="#B3B3B3" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9"/><rect xmlns="http://www.w3.org/2000/svg" x="283.548570905413" y="82.25" height="189.75" width="40.72571454729353" fill="#333333" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9"/><text xmlns="http://www.w3.org/2000/svg" x="0" y="0" text-anchor="middle" transform="translate(283.548570905413 291.84)" fill="#000000" font-size="19.84" font-family="Crimson Text">Type B</text><text text-anchor="middle" transform="translate(222.45999908447266 24)" fill="#000000" font-size="19.84" font-family="Crimson Text">Test Results for Two New </text><text text-anchor="middle" transform="translate(222.45999908447266 48)" fill="#000000" font-size="19.84" font-family="Crimson Text">Battery Recycling Processes</text><text text-anchor="middle" transform="translate(222.45999908447266 325.67999999999995)" fill="#000000" font-size="19.84" font-family="Crimson Text">Lithium-ion battery type</text><rect xmlns="http://www.w3.org/2000/svg" fill="none" x="100.38522338867188" y="342.84000000000003" height="71" width="194.22955322265625" stroke="#000000" stroke-linejoin="mitre" stroke-width="0.9"/><rect xmlns="http://www.w3.org/2000/svg" x="107.38522338867188" y="354.84000000000003" height="12" width="12" fill="#B3B3B3" stroke="#000000" stroke-linejoin="mitre" stroke-width="0.9"/><text transform="translate(129.38522338867188 366.84000000000003)" text-anchor="top" fill="#000000" font-size="19.84" font-family="Crimson Text"> recycling process 1</text><rect xmlns="http://www.w3.org/2000/svg" x="107.38522338867188" y="386.84000000000003" height="12" width="12" fill="#333333" stroke="#000000" stroke-linejoin="mitre" stroke-width="0.9"/><text transform="translate(129.38522338867188 398.84000000000003)" text-anchor="top" fill="#000000" font-size="19.84" font-family="Crimson Text"> recycling process 2</text></g></svg></figure><div class="sr-only" role="region" aria-label="Long description for bar graph titled Test Results for Two New Battery Recycling Processes"><ul>
<li>For each data category, the following bars are shown:<br/>
<ul>
<li>recycling process 1</li>
<li>recycling process 2</li>
</ul>
</li>
<li>All values are approximate.</li>
<li>The Lithium recovered data for the 2 categories are as follows:<br/>
<ul>
<li>Type A:<br/>
<ul>
<li>recycling process 1: 30%</li>
<li>recycling process 2: about halfway between 50% and 60%</li>
</ul>
</li>
<li>Type B:<br/>
<ul>
<li>recycling process 1: about halfway between 30% and 40%</li>
<li>recycling process 2: about halfway between 70% and 80%</li>
</ul>
</li>
</ul>
</li>
</ul></div>
<p>A team of scientists wants to improve the recycling of two of the most common types of lithium-ion batteries used in electronic devices. The team tested two new processes that involve grinding battery materials and aluminum foil together. The highest percentage of lithium recovered in the tests was closest to <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most effectively uses data from the graph to complete the statement?</p>$SATQ$, $SATQ$[{"id":"e0700da1-e101-4e96-aa85-0eb4d8f405e0","content":"<p>75%.</p>"},{"id":"e4f1f7f3-2a6e-4691-8e77-367a391b6c2c","content":"<p>10%.</p>"},{"id":"ede2710a-8e02-4d71-949d-0475ef0a09e7","content":"<p>45%.</p>"},{"id":"7948c519-855c-418a-8cba-d25df40f2dd3","content":"<p>20%.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["e0700da1-e101-4e96-aa85-0eb4d8f405e0"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most effectively uses data from the graph to complete the statement. The graph shows test results for two new battery recycling processes used with two types of lithium-ion batteries, type A and type B. According to the graph, recycling process 2 recovered the highest percentage of lithium in the tests: recovering about 75% from lithium-ion battery type B.</p><p>Choice B is incorrect because, according to the graph, the highest percentage of lithium recovered in the tests was 75%, not 10%. In fact, none of the tests recovered exactly 10% of lithium from a recycling process. Choice C is incorrect because, according to the graph, the highest percentage of lithium recovered in the tests was 75%, not 45%. In fact, none of the tests recovered exactly 45% of lithium from a recycling process. Choice D is incorrect because, according to the graph, the highest percentage of lithium recovered in the tests was 75%, not 20%. In fact, none of the tests recovered exactly 20% of lithium from a recycling process.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"5c73f0cc","external_id":"e9f142be-2f7c-44eb-a99a-aa5eb0e586ac","vaultid":null,"uId":"db03de1d-affc-482e-91a4-e948a8463b8c","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<figure class=\"image\"><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"380\" height=\"424.84\" viewBox=\"0 0 380 424.84\" role=\"img\" aria-label=\"Long description for bar graph titled Test Results for Two New Battery Recycling Processes. The horizontal axis is labeled Lithium-ion battery type. 2 data categories are shown. The vertical axis is labeled Lithium recovered, in percent. It ranges from 0 to 80 in increments of 10. Refer to long description.\"><g id=\"ed420550-79eb-48d4-af01-cd27cdd08afd\" data-name=\"Layer 1\"><defs>\n      <pattern id=\"bar4\" x=\"0\" y=\"0\" width=\"10\" height=\"100\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(50)\">\n        <rect x=\"0\" y=\"0\" width=\"5\" height=\"100\" fill=\"#CDCDCD\"/>\n        <rect x=\"5\" y=\"0\" width=\"5\" height=\"100\" fill=\"#444444\"/>\n      </pattern>\n    </defs><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"79.91999816894531\" y1=\"72\" x2=\"365\" y2=\"72\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"73.91999816894531\" y1=\"72\" x2=\"85.91999816894531\" y2=\"72\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(67.91999816894531 78)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">80</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"79.91999816894531\" y1=\"97\" x2=\"365\" y2=\"97\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" strok