nsform="translate(75.3203125 162)">70</text><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="87.3203125" x2="385" xmlns="http://www.w3.org/2000/svg" y1="176" y2="176"></line><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="81.3203125" x2="93.3203125" xmlns="http://www.w3.org/2000/svg" y1="176" y2="176"></line><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="end" transform="translate(75.3203125 182)">60</text><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="87.3203125" x2="385" xmlns="http://www.w3.org/2000/svg" y1="196" y2="196"></line><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="81.3203125" x2="93.3203125" xmlns="http://www.w3.org/2000/svg" y1="196" y2="196"></line><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="end" transform="translate(75.3203125 202)">50</text><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="87.3203125" x2="385" xmlns="http://www.w3.org/2000/svg" y1="216" y2="216"></line><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="81.3203125" x2="93.3203125" xmlns="http://www.w3.org/2000/svg" y1="216" y2="216"></line><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="end" transform="translate(75.3203125 222)">40</text><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="87.3203125" x2="385" xmlns="http://www.w3.org/2000/svg" y1="236" y2="236"></line><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="81.3203125" x2="93.3203125" xmlns="http://www.w3.org/2000/svg" y1="236" y2="236"></line><text fill="#000000" font-family="Crimson Text"